('780c48da-fb81-56b9-9f85-9ebe1eb9b9ba', '4050c62d-c61b-5d26-bff3-59d31175c284', 'The sum of the natural and driving frequencies', 'D', false, 3),
('13096fb5-ee1b-586a-a7d1-afd15cb92507', 'd8a84b2b-c643-544f-885a-1e33d0f8d3ed', 'Using a larger mass', 'A', false, 0),
