('d63cea4f-e73f-532e-a077-c00fa219b83c', '2950b659-e222-5252-a524-a1b3c9b75045', 'It oscillates at its natural frequency with a large amplitude', 'A', false, 0),
('fd69efb1-3285-5f5b-884c-ea6babf2fddb', '2950b659-e222-5252-a524-a1b3c9b75045', 'It does not move at all', 'B', false, 1),
('d9e9ea45-0332-5ebe-a50a-b991e8f0083e', '2950b659-e222-5252-a524-a1b3c9b75045', 'It oscillates at the driving frequency, exactly out of step with the driver', 'C', false, 2),
('ec5283f9-5d23-5e10-9f7c-09227ab6d564', '2950b659-e222-5252-a524-a1b3c9b75045', 'It oscillates at the driving frequency with a small amplitude, roughly in step with the driver', 'D', true, 3),
('605a70c4-a952-537a-9c5b-0930175b78fa', '7392cba6-4d53-5ed5-ad24-4e463034fb28', 'The string tension does not depend on the mass', 'A', false, 0),
('e4e27faa-d967-5651-a2f0-3ab9723d313e', '7392cba6-4d53-5ed5-ad24-4e463034fb28', 'Both the restoring force and the inertia are proportional to the mass, so the mass cancels', 'B', true, 1),
('942e404b-25af-5221-ad9d-936c6d86b0e7', '7392cba6-4d53-5ed5-ad24-4e463034fb28', 'Gravity does not act on heavier objects', 'C', false, 2),
('65dd3931-5d9f-577a-88ab-676b292d5b37', '7392cba6-4d53-5ed5-ad24-4e463034fb28', 'The period depends only on amplitude', 'D', false, 3),
('99875b4a-ddad-5632-904e-3f7318382335', '6d88656b-422d-5b2a-bf5d-5a1b5a2cd91b', 'Both periods increase', 'A', false, 0),
('73045ac5-d8d2-5031-8d3d-356f091760a4', '6d88656b-422d-5b2a-bf5d-5a1b5a2cd91b', 'Both periods are unchanged', 'B', false, 1),
('df789dea-25ca-5285-b568-5f843a3face4', '6d88656b-422d-5b2a-bf5d-5a1b5a2cd91b', 'The pendulum''s period increases; the mass–spring period is unchanged', 'C', true, 2),
('b3c80998-15eb-5e4c-8c84-46ba75b97f03', '6d88656b-422d-5b2a-bf5d-5a1b5a2cd91b', 'The mass–spring period increases; the pendulum''s is unchanged', 'D', false, 3),
('885be8f8-b28d-534a-98a7-21b8aa21a939', 'f91dcff2-9caa-563d-9ae8-a749dc03c5dd', 'The formula assumes small angles; at larger amplitudes the restoring force is less than proportional to displacement', 'A', true, 0),
('a72c8abe-3fb7-5b89-afb9-fd8faa785b0a', 'f91dcff2-9caa-563d-9ae8-a749dc03c5dd', 'Air resistance increases the period a lot', 'B', false, 1),
('01b5702e-0dde-5d17-9f0a-d68170d823e2', 'f91dcff2-9caa-563d-9ae8-a749dc03c5dd', 'The bob''s mass was too large', 'C', false, 2),
('553a004b-1787-570f-be4c-8f214f08b4c6', 'f91dcff2-9caa-563d-9ae8-a749dc03c5dd', 'The formula only works for 1 m pendulums', 'D', false, 3),
('6dfc1935-08f7-5c80-9d8f-a835933ccb19', '29b3fe3e-b36d-5ca6-82e1-5fae06299621', 'As often as possible', 'A', false, 0),
('7c65cc0a-e7d5-502f-a7ad-f71de2e74895', '29b3fe3e-b36d-5ca6-82e1-5fae06299621', 'Once every two seconds whatever the swing does', 'B', false, 1),
('f194397d-80f1-5e4a-b502-81441d75223f', '29b3fe3e-b36d-5ca6-82e1-5fae06299621', 'At twice the natural frequency, as it comes towards her', 'C', false, 2),
('d7f39563-4664-5dd1-ae53-a4e29ea4fdbb', '29b3fe3e-b36d-5ca6-82e1-5fae06299621', 'Once per swing, at the swing''s natural frequency, as it moves away from her', 'D', true, 3),
('3fa5a07c-d11c-5735-9d8b-17d18c2dfd65', 'fcdd6a45-47cc-5dc9-92a2-9ef9d8007f21', 'Its mass and its length', 'A', false, 0),
('7a4bff3a-4ad8-59ab-9578-7f55c600f54f', 'fcdd6a45-47cc-5dc9-92a2-9ef9d8007f21', 'Its length and the gravitational field strength', 'B', true, 1),
('4a4a1aa0-61d7-5b92-881c-67ed72ccdb6f', 'fcdd6a45-47cc-5dc9-92a2-9ef9d8007f21', 'Its amplitude and its mass', 'C', false, 2),
('19ebf632-b795-5455-a974-e65e7cd163a4', 'fcdd6a45-47cc-5dc9-92a2-9ef9d8007f21', 'Its length and its amplitude', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('9e3c22da-d8da-5b55-9c30-358b041d234f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 7, 7, 'A student times 10 oscillations of a mass on a spring as 8.6 s. Calculate the period.', NULL, 1, 'numeric'::answer_type, '0.86', 's', false, NULL, false, NULL, 'T = 8.6 ÷ 10 = 0.86 s. Mark scheme (1 mark). A1: T = 0.86 s.', 1),
('18bd1e8e-bb59-506f-a907-1df4d14397e7', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 8, 8, 'A heart monitor shows 72 beats in one minute. Calculate the frequency in hertz.', NULL, 1, 'numeric'::answer_type, '1.2', 'Hz', false, NULL, false, NULL, 'f = 72 ÷ 60 = 1.2 Hz. Mark scheme (1 mark). A1: f = 1.2 Hz.', 1),
('7373eb95-8a43-5dc4-931e-f78a4fbac097', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 9, 9, 'A guitar string vibrates 330 times each second. Calculate the period of its vibration in milliseconds.', NULL, 1, 'numeric'::answer_type, '3.03 ms', 'ms', false, NULL, false, NULL, 'T = 1/f = 1 ÷ 330 = 0.00303 s. In ms: 0.003030 × 1000 = 3.03 ms. Mark scheme (2 marks). C1: T = 1/f. A1: T = 3.03 ms.', 2),
('8696d171-7cc0-5a3a-8797-f783cb0ca923', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 10, 10, 'A data-logger trace of an oscillating trolley shows the displacement going from +4.0 cm to −4.0 cm and back. What is the amplitude?', NULL, 1, 'multiple_choice'::answer_type, '4.0 cm', NULL, false, NULL, false, NULL, 'Amplitude is the maximum displacement from the equilibrium position: 4.0 cm (the peak-to-peak value is 8.0 cm). Mark scheme (1 mark). B1: C (4.0 cm).', 1),
('0d623e11-8030-5bbb-923a-a5769427e7ca', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 11, 11, 'Why is a "fiducial marker" (a fixed pin at the centre of the swing) used when timing a pendulum?', NULL, 1, 'multiple_choice'::answer_type, 'It is easiest to judge the instant the bob passes the centre, where it moves fastest', NULL, false, NULL, false, NULL, 'At the centre the bob moves fastest, so the moment it passes is sharp; at the ends it lingers, making the instant hard to judge. Mark scheme (1 mark). B1: A (It is easiest to judge the instant the bob passes the centre, where it moves fastest).', 1),
('6129f348-75e6-54a2-9cd1-b90f65eb0f72', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 12, 12, 'Which instrument would best record the displacement–time graph of a vibrating loudspeaker cone at 200 Hz?', NULL, 1, 'multiple_choice'::answer_type, 'A motion sensor or laser and an oscilloscope/data logger', NULL, false, NULL, false, NULL, 'At 200 Hz each cycle lasts 5 ms; only an electronic sensor and fast recorder can follow it. Mark scheme (1 mark). B1: D (A motion sensor or laser and an oscilloscope/data logger).', 1),
('63fd64e5-23ed-546e-9502-318621aa686f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 13, 13, 'On an oscilloscope screen, one complete cycle of a trace spans 4.0 divisions. The time base is 2.0 ms per division. Calculate the frequency of the oscillation.', NULL, 1, 'numeric'::answer_type, '125', 'Hz', false, NULL, false, NULL, 'T = 4.0 × 2.0 = 8.0 ms = 8.0 × 10⁻³ s. f = 1/T = 1 ÷ 8.0 × 10⁻³ = 125 Hz. Mark scheme (2 marks). C1: T = divisions × time base. A1: f = 125 Hz.', 2),
('ea2ef2e5-1c91-5605-a4a3-942facb73b42', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 14, 14, 'A wing of a hummingbird beats with a frequency of 55 Hz. How many beats does it make in 3.0 s?', NULL, 1, 'numeric'::answer_type, '165', NULL, false, NULL, false, NULL, 'number = ft = 55 × 3.0 = 165. Mark scheme (2 marks). C1: N = ft. A1: beats = 165.', 2),
('c78d8c04-754d-51c8-9899-ece2f4f37c57', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 15, 15, 'Why is it better to time 20 oscillations than one?', NULL, 1, 'multiple_choice'::answer_type, 'The reaction-time error is shared over 20 periods, so the percentage uncertainty in T is smaller', NULL, false, NULL, false, NULL, 'Starting and stopping errors (≈ 0.2 s) are the same however many oscillations are timed, so dividing by 20 makes their effect on T much smaller. Mark scheme (1 mark). B1: B (The reaction-time error is shared over 20 periods, so the percentage uncertainty in T is smaller).', 1),
('d81b8fbf-9692-5634-873e-6aae28811a0c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 16, 16, 'A pendulum makes 25 complete oscillations in 40.0 s. Calculate its frequency.', NULL, 1, 'numeric'::answer_type, '0.625', 'Hz', false, NULL, false, NULL, 'f = number ÷ time = 25 ÷ 40.0 = 0.625 Hz. Mark scheme (2 marks). C1: f = N/t. A1: f = 0.625 Hz.', 2),
('61dd2541-74d6-5a5e-bf53-ae9683c44d0d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 17, 17, 'A displacement–time graph of an oscillation repeats every 0.40 s. What is its frequency?', NULL, 1, 'multiple_choice'::answer_type, '2.5 Hz', NULL, false, NULL, false, NULL, 'f = 1/T = 1 ÷ 0.40 = 2.5 Hz. Mark scheme (1 mark). B1: C (2.5 Hz).', 1),
('fc3a2bb4-da5e-55cc-bd28-9afbd5b4e03f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 18, 18, 'A twanged ruler appears stationary in the light of a strobe flashing 24 times a second, and at no higher flash rate up to 48 Hz. What is the frequency of the ruler?', NULL, 1, 'multiple_choice'::answer_type, '24 Hz', NULL, false, NULL, false, NULL, 'The ruler looks frozen when it completes a whole number of vibrations between flashes. The highest flash rate giving a single frozen image equals its frequency: 24 Hz. Mark scheme (1 mark). B1: A (24 Hz).', 1),
('b4965202-4226-507c-aa02-01a22fd42d15', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 19, 19, 'A student says the period of an oscillation is "the time from one end to the other end of the swing". What is wrong?', NULL, 1, 'multiple_choice'::answer_type, 'That is only half a period: the period is the time for one complete oscillation, back to the same point moving the same way', NULL, false, NULL, false, NULL, 'One end to the other is half an oscillation. A full period returns to the starting position with the same direction of motion. Mark scheme (1 mark). B1: D (That is only half a period: the period is the time for one complete oscillation, back to the same point moving the same way).', 1),
('28f5ef05-4f17-52a8-acbd-795948d6c4cd', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 20, 20, 'A displacement–time graph shows 6 complete cycles in 1.5 s. Calculate the period.', NULL, 1, 'numeric'::answer_type, '0.25', 's', false, NULL, false, NULL, 'T = 1.5 ÷ 6 = 0.25 s. Mark scheme (2 marks). C1: T = t/N. A1: T = 0.25 s.', 2),
('eeae7d42-d98e-592a-be19-213c0adbc6ec', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 21, 21, 'Which measurement shows that an oscillation is isochronous (its period does not depend on amplitude)?', NULL, 1, 'multiple_choice'::answer_type, 'The time for 10 oscillations is the same for small and for larger releases', NULL, false, NULL, false, NULL, 'Isochronous means equal times: timing the same number of swings at different amplitudes and finding no change. Mark scheme (1 mark). B1: B (The time for 10 oscillations is the same for small and for larger releases).', 1),
('23048ef7-e494-5761-b2f6-4ef7e1c41523', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 22, 22, 'A metronome is set to 120 beats per minute, with one beat at each end of its swing. Calculate the period of its oscillation.', NULL, 1, 'numeric'::answer_type, '1', 's', false, NULL, false, NULL, 'Two beats per oscillation: 120 beats per minute = 60 oscillations per minute, so T = 60 ÷ 60 = 1.0 s. Mark scheme (2 marks). C1: two beats per cycle. A1: T = 1.0 s.', 2),
('6dfa6a2a-a26d-5069-a4ee-5978aadc385e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 23, 23, 'A student times 20 oscillations of a pendulum as 31.6 s, with an uncertainty of ±0.2 s in each timing. Calculate the period and its percentage uncertainty. Give the percentage uncertainty.', NULL, 2, 'numeric'::answer_type, '0.6329', '%', false, NULL, false, NULL, 'T = 31.6 ÷ 20 = 1.58 s. Absolute uncertainty in T = 0.2 ÷ 20 = 0.01 s. Percentage = 0.01 ÷ 1.58 × 100 = 0.63 %. Mark scheme (3 marks). C1: T = t/20. C1: uncertainty divided by 20. C1: percentage.', 3),
('361df53f-fdb9-5068-ba47-d2a1d47b742f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 24, 24, 'An oscilloscope shows a sinusoidal trace with peak-to-peak height 5.6 divisions on a setting of 0.50 cm per division (the trace shows displacement of a vibrating plate). One cycle is 3.2 divisions wide at 5.0 ms per division. Calculate the amplitude of the plate in cm.', NULL, 2, 'numeric'::answer_type, '1.4 cm', 'cm', false, NULL, false, NULL, 'Peak-to-peak = 5.6 × 0.50 = 2.8 cm, so amplitude = 2.8 ÷ 2 = 1.4 cm. (Period = 3.2 × 5.0 = 16 ms.). Mark scheme (3 marks). C1: peak-to-peak × scale. C1: halve for amplitude. B1: period read correctly.', 3),
('fe6f2114-f7f6-5152-b017-88e9d7a3d7cb', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 25, 25, 'A mass on a spring is filmed at 30 frames per second, and its oscillation spans exactly 18 frames per cycle. A student claims the frequency is 18 Hz. What is the correct frequency?', NULL, 2, 'multiple_choice'::answer_type, '1.7 Hz', NULL, false, NULL, false, NULL, 'T = 18 frames ÷ 30 frames s⁻¹ = 0.60 s, so f = 1/0.60 = 1.7 Hz. Mark scheme (3 marks). C1: T = frames/frame rate. C1: f = 1/T. A1: C (1.7 Hz).', 3),
('e6c2c8a9-f895-5291-b8b5-ed629e3094a1', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 26, 26, 'Readings of time for 10 oscillations of a spring: 7.62 s, 7.58 s, 7.70 s, 7.66 s. Calculate the mean period and its absolute uncertainty (half the range of the readings divided by 10). Give the mean period.', NULL, 2, 'numeric'::answer_type, '0.764', 's', false, NULL, false, NULL, 'Mean time = (7.62 + 7.58 + 7.70 + 7.66) ÷ 4 = 7.640 s, so T = 7.640 ÷ 10 = 0.764 s. Uncertainty = ½ × (7.70 − 7.58) ÷ 10 = 0.006 s. Mark scheme (3 marks). C1: mean of readings. C1: divide by 10. C1: uncertainty from half-range.', 3),
('f92e8bc2-c6cb-59ec-97e2-a7244619e865', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 27, 27, 'A student wants to show that a vibrating mass moves with simple harmonic motion using a motion sensor. Which observation would support this?', NULL, 2, 'multiple_choice'::answer_type, 'The displacement–time graph is sinusoidal with a period that does not change with amplitude', NULL, false, NULL, false, NULL, 'S.h.m. gives a sinusoidal x–t graph and an amplitude-independent period. Mark scheme (3 marks). C1: sinusoidal. C1: period independent of amplitude. A1: A (The displacement–time graph is sinusoidal with a period that does not change with amplitude).', 3),
('fbfa2db3-3e8b-58b1-b9f7-9b9111518e33', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 28, 28, 'A light gate records a pendulum bob of width 2.0 cm blocking the beam for 25 ms as it passes the lowest point. The pendulum''s amplitude is 8.0 cm and its period is 1.5 s. (a) Calculate the maximum speed from the light gate. (b) Compare with 2πA/T. Give the speed from (a).', NULL, 2, 'numeric'::answer_type, '0.8', 'm s⁻¹', false, NULL, false, NULL, '(a) v = width ÷ time = 0.020 ÷ 0.025 = 0.80 m s⁻¹. (b) 2πA/T = 2π × 0.080 ÷ 1.5 = 0.335 m s⁻¹: close, slightly larger (the bob slows a little across the beam). Mark scheme (4 marks). C1: v = d/t with SI units. C1: v_max = 2πA/T. B1: comparison. A1: v = 0.80 m s⁻¹.', 4),
('bc032f58-3065-5a70-b83a-4bd9b101e3ac', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 29, 29, 'An oscillation on a data logger has 8 complete cycles in a 5.0 s recording window. Calculate the angular frequency.', NULL, 2, 'numeric'::answer_type, '10.05', 'rad s⁻¹', false, NULL, false, NULL, 'f = 8 ÷ 5.0 = 1.6 Hz. ω = 2πf = 2π × 1.6 = 10.1 rad s⁻¹. Mark scheme (3 marks). C1: f = N/t. C1: ω = 2πf. A1: ω = 10.1 rad s⁻¹.', 3),
('2e5d7981-1e26-526b-b050-d843c977a17d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 30, 30, 'When timing pendulum oscillations, a student starts the stopwatch and says "one" as the bob passes the marker the first time. She stops after saying "twenty". How many complete oscillations has she timed?', NULL, 2, 'multiple_choice'::answer_type, '19', NULL, false, NULL, false, NULL, 'Counting "one" at the start means the count is one ahead: from "one" to "twenty" is 19 complete oscillations. (Start the count at zero to avoid this.). Mark scheme (3 marks). C1: first pass is zero. C1: 19 intervals. A1: D (19).', 3),
('a9b86e7b-9ea8-5158-b552-c79c6b6acb25', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 31, 31, 'A vibration sensor shows a trace of period 2.5 ms. Calculate the frequency and the number of cycles in 0.20 s. Give the number of cycles.', NULL, 2, 'numeric'::answer_type, '80', NULL, false, NULL, false, NULL, 'f = 1 ÷ 2.5 × 10⁻³ = 400 Hz. N = ft = 400 × 0.20 = 80. Mark scheme (3 marks). C1: f = 1/T. C1: N = ft. A1: N = 80.', 3),
('614a01d1-fa32-59c7-a6f9-8df47b105c31', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 32, 32, 'A student times 10 oscillations of a pendulum five times and gets 14.2, 14.3, 14.1, 15.6 and 14.2 s. What should she do with the 15.6 s reading?', NULL, 2, 'multiple_choice'::answer_type, 'Treat it as anomalous: repeat that timing and leave it out of the mean if confirmed wrong', NULL, false, NULL, false, NULL, '15.6 s is far from the other four (≈ 14.2 s), probably a miscount. It should be repeated and excluded from the mean. Mark scheme (4 marks). C1: identifies anomaly. C1: repeat/exclude. C1: mean of consistent values. A1: B (Treat it as anomalous: repeat that timing and leave it out of the mean if confirmed wrong).', 4),
('db49e72d-50f8-55df-bf36-4d82c8b91010', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 33, 33, 'A student measures the period of a mass–spring system for masses 0.10, 0.20, 0.30, 0.40 kg and gets T = 0.41, 0.58, 0.71, 0.82 s. Use the 0.40 kg reading to calculate the spring constant.', NULL, 2, 'numeric'::answer_type, '23.49', 'N m⁻¹', false, NULL, false, NULL, 'T = 2π√(m/k), so k = 4π²m/T² = 4π² × 0.40 ÷ 0.82² = 23.5 N m⁻¹. Mark scheme (4 marks). C1: T² = 4π²m/k. C1: rearranged. C1: substitution. A1: k = 23.5 N m⁻¹.', 4),
('65f1bbc7-18d9-5768-820c-53a92b9e1f32', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 34, 34, 'A buoy bobs up and down on waves, rising from its lowest to its highest point in 1.8 s, through a height of 1.2 m. State the amplitude and calculate the period of its oscillation. Give the period.', NULL, 2, 'numeric'::answer_type, '3.6', 's', false, NULL, false, NULL, 'Lowest to highest is half a cycle, so T = 2 × 1.8 = 3.6 s. Amplitude = 1.2 ÷ 2 = 0.60 m. Mark scheme (3 marks). C1: half cycle. C1: T doubled. B1: amplitude 0.60 m.', 3),
('cc6001dc-ebc2-517e-a698-6b46afafcccd', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 35, 35, 'Which change would make the timing of a pendulum period more precise?', NULL, 2, 'multiple_choice'::answer_type, 'Timing more oscillations in each measurement', NULL, false, NULL, false, NULL, 'More oscillations reduce the fractional effect of the reaction-time uncertainty. Timing at the centre (not the end) also helps. Mark scheme (3 marks). C1: more oscillations. C1: reduces percentage uncertainty. A1: C (Timing more oscillations in each measurement).', 3),
('9c1629a3-c297-5589-9324-2166bf6b2ef6', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 36, 36, 'An oscilloscope time base is set at 0.20 ms per division. A sound wave trace shows 2.5 cycles across 10 divisions. Calculate the frequency.', NULL, 2, 'numeric'::answer_type, '1250', 'Hz', false, NULL, false, NULL, 'Time across screen = 10 × 0.20 = 2.0 ms. T = 2.0 ÷ 2.5 = 0.80 ms. f = 1 ÷ 8.0 × 10⁻⁴ = 1250 Hz. Mark scheme (3 marks). C1: total time. C1: T = time/cycles. C1: f = 1/T.', 3),
('b8a8bf69-82d4-5130-a9ce-50f2a779ff5f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 37, 37, 'A student counts 30 oscillations of a pendulum in 36.6 s. Another student times 3 oscillations as 3.6 s. Both have a reaction-time uncertainty of 0.2 s. Calculate the percentage uncertainty in the period for the first student.', NULL, 2, 'numeric'::answer_type, '0.5464', '%', false, NULL, false, NULL, '% uncertainty = 0.2 ÷ 36.6 × 100 = 0.55 % (the second student: 0.2 ÷ 3.6 × 100 = 5.6 %, ten times worse). Mark scheme (3 marks). C1: uncertainty/total time. C1: × 100. B1: comparison.', 3),
('cf5909b8-c693-569d-9f50-d7e3c82da49c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 38, 38, 'A student investigates how the period T of a mass–spring system depends on the mass m. Readings: m = 0.10, 0.20, 0.30, 0.40, 0.50 kg; T = 0.40, 0.56, 0.69, 0.80, 0.89 s. (a) Show that T² is proportional to m. (b) Determine the gradient of T² against m. (c) Calculate the spring constant. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '24.92', 'N m⁻¹', false, NULL, false, NULL, '(a) T²/m: 0.40² ÷ 0.10 = 1.60, 0.56² ÷ 0.20 = 1.57, 0.69² ÷ 0.30 = 1.59, 0.80² ÷ 0.40 = 1.60, 0.89² ÷ 0.50 = 1.58 s² kg⁻¹: constant. (b) gradient ≈ 0.89² ÷ 0.50 = 1.58 s² kg⁻¹. (c) gradient = 4π²/k, so k = 4π² ÷ 1.584 = 24.9 N m⁻¹. Mark scheme (6 marks). M1: T²/m calculated for several points. A1: constant. C1: gradient. M1: gradient = 4π²/k. C1: substitution. A1: k = 24.9 N m⁻¹.', 6),
('46b76375-ef15-58dc-9ec2-7bab8fe26943', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 39, 39, 'Timing 20 swings of a pendulum gives 35.4 s ± 0.3 s. The length is 0.780 m ± 0.002 m. (a) Calculate g using T = 2π√(L/g). (b) Calculate the percentage uncertainties in T and L. (c) Calculate the percentage uncertainty in g. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.951', '%', false, 0.05, false, NULL, '(a) T = 35.4 ÷ 20 = 1.77 s. g = 4π²L/T² = 4π² × 0.780 ÷ 1.77² = 9.83 N kg⁻¹. (b) %T = 0.3 ÷ 35.4 × 100 = 0.847 %, %L = 0.002 ÷ 0.780 × 100 = 0.256 %. (c) g ∝ L/T², so %g = %L + 2 × %T = 0.256 + 2 × 0.847 = 1.95 %. Mark scheme (5 marks). C1: T from 20 swings. A1: g. A1: %T and %L. M1: %g = %L + 2%T. A1: %g = 2.0%.', 5),
('362898b9-8dc8-5d3b-b106-1a88b3ca9dbe', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 40, 40, 'A vibrating plate is observed with a stroboscope. The plate appears stationary at flash frequencies of 50 Hz, 25 Hz and 16.7 Hz, but not at any frequency between 50 Hz and 100 Hz. At 100 Hz it appears frozen but with two images. (a) Explain why it appears stationary at several flash frequencies. (b) Deduce the frequency of the plate. (c) Explain the double image at 100 Hz. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '50', 'Hz', false, NULL, false, NULL, '(a) The plate appears frozen whenever it completes a whole number of cycles between flashes: at f, f/2, f/3 … (b) The highest single-image freezing frequency is the plate''s frequency. The others fit: 25 × 2 = 50 and 16.7 × 3 = 50 Hz. (c) At 100 Hz the flashes come twice per cycle, catching the plate at two different positions. Mark scheme (6 marks). B1: whole number of cycles between flashes. M1: f, f/2, f/3 pattern. A1: 50 Hz. B1: 100 Hz = twice per cycle. B1: two positions seen. B1: correct reasoning for highest frequency.', 6),
('5af9de0b-11c2-579a-a0ea-b1cbdf6768f4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 41, 41, 'A motion sensor records the displacement x of a trolley oscillating between springs: x = 0 at t = 0, +3.0 cm at t = 0.30 s, 0 at t = 0.60 s, −3.0 cm at t = 0.90 s, 0 at t = 1.20 s. (a) State the amplitude and period. (b) Calculate the maximum speed, using v_max = 2πA/T. (c) State where in the cycle the trolley moves fastest. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.1571', 'm s⁻¹', false, NULL, false, NULL, '(a) A = 3.0 cm, T = 1.20 s. (b) v_max = 2πA/T = 2π × 0.030 ÷ 1.20 = 0.157 m s⁻¹. (c) Passing through x = 0 (t = 0, 0.60 s, 1.20 s). Mark scheme (5 marks). B1: A = 3.0 cm. B1: T = 1.20 s. C1: v_max = 2πA/T. A1: v_max = 0.157 m s⁻¹. B1: at equilibrium.', 5),
('656a9364-c2f7-5a1a-93b3-9fb432bdac62', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 42, 42, 'A student uses a data logger to record a pendulum and finds the amplitude falls from 10.0 cm to 5.0 cm in 30 complete oscillations, each of period 1.20 s. (a) Calculate the time taken for the amplitude to halve. (b) State what fraction of the energy remains when the amplitude has halved. (c) Predict the amplitude after 60 oscillations, assuming the same fractional loss per oscillation. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.5 cm', 'cm', false, NULL, false, NULL, '(a) t = 30 × 1.20 = 36 s. (b) E ∝ A², so (½)² = ¼ of the energy remains. (c) Each 30 oscillations halves the amplitude, so after 60 it is 10.0 ÷ 4 = 2.5 cm. Mark scheme (6 marks). C1: t = 30T. A1: 36 s. B1: E ∝ A². B1: ¼. M1: halving every 30 oscillations. A1: 2.5 cm.', 6),
('6eea1cf9-1011-51bf-9dec-bd5076cd46c8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 43, 43, 'An oscilloscope (time base 1.0 ms per division) displays the output of a microphone placed near a vibrating tuning fork. Four complete cycles occupy 9.6 divisions. (a) Calculate the frequency of the fork. (b) The time base is changed to 0.50 ms per division. Calculate how many divisions one cycle now occupies. (c) Explain why the trace height falls slowly while the frequency stays the same. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '416.7', 'Hz', false, NULL, false, NULL, '(a) T = 9.6 × 1.0 ÷ 4 = 2.4 ms. f = 1 ÷ 2.4 × 10⁻³ = 417 Hz. (b) 2.4 ms ÷ 0.50 ms per division = 4.8 divisions. (c) Damping removes energy so the amplitude decreases, but the natural frequency of the fork does not change. Mark scheme (5 marks). C1: T from 4 cycles. A1: f = 417 Hz. C1: divisions = T/time base. A1: 4.8. B1: damping lowers amplitude, frequency unchanged.', 5),
('405ed446-6eea-5bfc-b82c-318bab739fc9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 44, 44, 'A girl on a trampoline bounces with a steady period of 1.6 s. A video shows her rising 1.2 m above the bed at the top of each bounce. (a) Calculate the time she spends in the air on each bounce, assuming she leaves and lands at the same level. (b) Calculate the time in contact with the bed. (c) Explain why this motion is periodic but not simple harmonic. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.6108', 's', false, NULL, false, NULL, '(a) Time to fall 1.2 m: t = √(2h/g) = √(2 × 1.2 ÷ 9.81) = 0.495 s, so air time = 2 × 0.495 = 0.989 s. (b) contact time = 1.6 − 0.9892 = 0.611 s. (c) It repeats regularly, but in the air the acceleration is constant (g), not proportional to displacement. Mark scheme (6 marks). C1: t = √(2h/g). A1: air time. C1: subtract from period. A1: t = 0.611 s. B1: periodic. B1: a not ∝ −x in flight.', 6),
('c8812487-617e-502e-86b9-9c337ed91457', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 45, 45, 'A position sensor records an oscillating glider: the displacement is +5.0 cm at t = 0, 0 at t = 0.35 s, −5.0 cm at t = 0.70 s and +5.0 cm again at t = 1.40 s. (a) State the amplitude and period. (b) Calculate the frequency. (c) Calculate the maximum speed of the glider. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.2244', 'm s⁻¹', false, NULL, false, NULL, '(a) A = 5.0 cm, T = 1.40 s. (b) f = 1 ÷ 1.40 = 0.714 Hz. (c) v_max = 2πA/T = 2π × 0.050 ÷ 1.40 = 0.224 m s⁻¹. Mark scheme (5 marks). B1: A = 5.0 cm. B1: T = 1.40 s. A1: f. C1: v_max = 2πA/T. A1: v_max = 0.224 m s⁻¹.', 5),
('b5b13a3d-8138-55e1-8ec1-6c3a2f8d6d3e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 46, 46, 'A student times a mass–spring system: t₁₀ (time for 10 oscillations) = 6.42, 6.38, 6.45, 6.40 s. (a) Calculate the mean period. (b) Estimate the absolute uncertainty in the period from the spread of readings. (c) The mass is 0.250 kg. Calculate the spring constant. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '24', 'N m⁻¹', false, NULL, false, NULL, '(a) mean t₁₀ = (6.42 + 6.38 + 6.45 + 6.40) ÷ 4 = 6.412 s, so T = 0.6412 s. (b) half-range = (6.45 − 6.38) ÷ 2 = 0.035 s for 10, so ±0.004 s. (c) k = 4π²m/T² = 4π² × 0.250 ÷ 0.6412² = 24.0 N m⁻¹. Mark scheme (6 marks). C1: mean. A1: T. B1: uncertainty from half-range ÷ 10. C1: k = 4π²m/T². C1: substitution. A1: k = 24.0 N m⁻¹.', 6),
('2187555c-a2d8-5512-85de-18a697237214', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 47, 47, 'A digital camera filming at 240 frames per second records a vibrating spring. The spring takes 18 frames for one complete oscillation, and its ends move 12 mm apart. (a) Calculate the period. (b) State the amplitude. (c) Calculate the maximum speed of the end of the spring. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.5027', 'm s⁻¹', false, NULL, false, NULL, '(a) T = 18 ÷ 240 = 0.075 s. (b) A = 12 ÷ 2 = 6.0 mm. (c) v_max = 2πA/T = 2π × 0.0060 ÷ 0.075 = 0.503 m s⁻¹. Mark scheme (5 marks). C1: T = frames/frame rate. A1: T. B1: A = 6.0 mm. C1: v_max = 2πA/T. A1: v_max = 0.503 m s⁻¹.', 5),
('c18d30ad-be6b-5b53-b789-2c7356ed9422', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 48, 48, 'An oscilloscope with time base 5.0 ms per division and y-gain 2.0 V per division shows the output of a vibration sensor (1.0 V per mm of displacement). One cycle spans 7.2 divisions and the peak-to-peak height is 4.4 divisions. (a) Calculate the frequency. (b) Calculate the amplitude of the vibration in mm. (c) Calculate the maximum speed of the vibrating surface. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.7679', 'm s⁻¹', false, NULL, false, NULL, '(a) T = 7.2 × 5.0 = 36 ms, f = 1 ÷ 0.036 = 27.8 Hz. (b) peak-to-peak = 4.4 × 2.0 = 8.8 V, so amplitude = 4.4 V = 4.4 mm. (c) v_max = 2πfA = 2π × 27.78 × 0.0044 = 0.768 m s⁻¹. Mark scheme (6 marks). C1: T from time base. A1: f. C1: voltage to displacement. A1: A = 4.4 mm. C1: v_max = 2πfA. A1: v_max = 0.768 m s⁻¹.', 6),
('10832c02-9fb6-51db-ac98-5d13af3c5fdc', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 49, 49, 'A student uses a light gate at the centre of a pendulum''s swing. The gate counts passes of the bob: 41 passes in 30.0 s, starting the clock at the first pass. (a) Calculate the number of complete oscillations. (b) Calculate the period. (c) Explain why counting passes of the centre gives two counts per oscillation. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.5', 's', false, NULL, false, NULL, '(a) The bob passes the centre twice per oscillation; 41 passes starting at zero mean 40 half-oscillations = 20 oscillations. (b) T = 30.0 ÷ 20 = 1.50 s. (c) In one oscillation the bob passes through the centre once in each direction. Mark scheme (5 marks). M1: 40 intervals between 41 passes. A1: 20 oscillations. C1: T = t/N. A1: T = 1.50 s. B1: two passes per cycle.', 5),
('48a0c748-356d-5465-adda-b2e390a9a1e9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 50, 50, 'A seismometer records an earthquake wave. On the record, 15 complete cycles span 6.0 s and the largest peak-to-peak trace is 3.6 mm. The instrument magnifies ground motion 1500 times. (a) Calculate the frequency of the ground vibration. (b) Calculate the amplitude of the ground''s motion. (c) Calculate the maximum acceleration of the ground. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.961e-4', 'm s⁻²', false, NULL, false, NULL, '(a) f = 15 ÷ 6.0 = 2.5 Hz. (b) trace amplitude = 3.6 ÷ 2 = 1.8 mm, ground amplitude = 1.8 ÷ 1500 = 1.2 × 10⁻³ mm = 1.2 × 10⁻⁶ m. (c) a_max = (2πf)²A = (2π × 2.5)² × 1.2 × 10⁻⁶ = 2.96 × 10⁻⁴ m s⁻². Mark scheme (6 marks). A1: f. C1: half the peak-to-peak. C1: ÷ magnification. A1: A. C1: a_max = ω²A. A1: a_max = 2.96 × 10⁻⁴ m s⁻².', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('70421818-b92f-5c2c-a548-e11d9c14cc23', '8696d171-7cc0-5a3a-8797-f783cb0ca923', '8.0 cm', 'A', false, 0),
('ebf1f533-761a-575d-8356-d8d2923277d8', '8696d171-7cc0-5a3a-8797-f783cb0ca923', '2.0 cm', 'B', false, 1),
('1e6c7d97-e36d-51be-a5a1-4f160a5a8509', '8696d171-7cc0-5a3a-8797-f783cb0ca923', '4.0 cm', 'C', true, 2),
('3bc92d02-cb13-53c5-ae87-8e9d32589e89', '8696d171-7cc0-5a3a-8797-f783cb0ca923', '16 cm', 'D', false, 3),
('528cfeac-b70c-5118-89f5-0cb2a23a7325', '0d623e11-8030-5bbb-923a-a5769427e7ca', 'It is easiest to judge the instant the bob passes the centre, where it moves fastest', 'A', true, 0),
('d9429098-3bfc-5b56-823b-167600f0ee5a', '0d623e11-8030-5bbb-923a-a5769427e7ca', 'It stops the bob swinging too far', 'B', false, 1),
('374f6c0c-b2de-5568-9be4-e9f1ac4ac7d0', '0d623e11-8030-5bbb-923a-a5769427e7ca', 'It makes the pendulum swing faster', 'C', false, 2),
('4482f40b-e3ea-507e-83de-1ca76a386953', '0d623e11-8030-5bbb-923a-a5769427e7ca', 'It reduces air resistance', 'D', false, 3),
('2e56d7b0-9a94-54b9-93a3-cbaec79ea3cb', '6129f348-75e6-54a2-9cd1-b90f65eb0f72', 'A stopwatch', 'A', false, 0),
('21123477-3788-55ad-bac2-0fdb96421f2c', '6129f348-75e6-54a2-9cd1-b90f65eb0f72', 'A metre rule and the naked eye', 'B', false, 1),
('370772f9-d8a9-5c27-a87d-3697a61e1ed5', '6129f348-75e6-54a2-9cd1-b90f65eb0f72', 'A spring balance', 'C', false, 2),
('2d297acf-c20d-54da-ab93-1292b64c9bba', '6129f348-75e6-54a2-9cd1-b90f65eb0f72', 'A motion sensor or laser and an oscilloscope/data logger', 'D', true, 3),
('fb5eedd7-7c2e-5908-b22b-9a162e5d7cec', 'c78d8c04-754d-51c8-9899-ece2f4f37c57', 'The pendulum speeds up after the first few swings', 'A', false, 0),
('7849858c-8764-55f3-bd99-f438d6df4d38', 'c78d8c04-754d-51c8-9899-ece2f4f37c57', 'The reaction-time error is shared over 20 periods, so the percentage uncertainty in T is smaller', 'B', true, 1),
('b5bb4ff3-d9de-59eb-a454-866e0611bd7d', 'c78d8c04-754d-51c8-9899-ece2f4f37c57', 'One oscillation is too long to time', 'C', false, 2),
('940d7bfc-73ba-5d05-b2f3-b7bac77dcae1', 'c78d8c04-754d-51c8-9899-ece2f4f37c57', 'The amplitude grows during 20 oscillations', 'D', false, 3),
('79abb3e3-9107-5223-a477-e3edc2d4f922', '61dd2541-74d6-5a5e-bf53-ae9683c44d0d', '0.40 Hz', 'A', false, 0),
('96b70185-93a1-5633-ab71-312782bc6934', '61dd2541-74d6-5a5e-bf53-ae9683c44d0d', '4.0 Hz', 'B', false, 1),
('a3afcd75-9f85-51ce-8d2e-107ce8412652', '61dd2541-74d6-5a5e-bf53-ae9683c44d0d', '2.5 Hz', 'C', true, 2),
('8f783d3e-a80d-5c1e-a522-6aa1763f541c', '61dd2541-74d6-5a5e-bf53-ae9683c44d0d', '25 Hz', 'D', false, 3),
('61edc5f5-2c8b-508f-a076-ef0a2142d2bc', 'fc3a2bb4-da5e-55cc-bd28-9afbd5b4e03f', '24 Hz', 'A', true, 0),
('1402353c-a103-5db4-a24d-9f1b88df523a', 'fc3a2bb4-da5e-55cc-bd28-9afbd5b4e03f', '12 Hz', 'B', false, 1),
('332e2f0a-d334-5723-a30b-3a7da9454909', 'fc3a2bb4-da5e-55cc-bd28-9afbd5b4e03f', '48 Hz', 'C', false, 2),
('f3156ef3-6372-51cf-9dd2-420808f70cd7', 'fc3a2bb4-da5e-55cc-bd28-9afbd5b4e03f', '2.0 Hz', 'D', false, 3),
('2c7651b7-e040-5bb9-a0a9-3eba4f874a42', 'b4965202-4226-507c-aa02-01a22fd42d15', 'Nothing is wrong', 'A', false, 0),
('b800242e-d289-5f9d-a94e-ba427d8fe944', 'b4965202-4226-507c-aa02-01a22fd42d15', 'That is twice the period', 'B', false, 1),
('b3201c96-2fc5-5800-ac96-be5fb5d1983f', 'b4965202-4226-507c-aa02-01a22fd42d15', 'The period is the time to reach maximum speed', 'C', false, 2),
('97d7acb8-a61b-5c13-9c18-bc49cbbfbb0e', 'b4965202-4226-507c-aa02-01a22fd42d15', 'That is only half a period: the period is the time for one complete oscillation, back to the same point moving the same way', 'D', true, 3),
('1a45fd7f-dd00-531d-b26c-6a2c520bb452', 'eeae7d42-d98e-592a-be19-213c0adbc6ec', 'The amplitude decreases with time', 'A', false, 0),
('ccee1a9a-1ade-54f3-8330-74cf1dbd6664', 'eeae7d42-d98e-592a-be19-213c0adbc6ec', 'The time for 10 oscillations is the same for small and for larger releases', 'B', true, 1),
('eab00abb-d4e5-5b57-9ffe-5af7e8eddcdb', 'eeae7d42-d98e-592a-be19-213c0adbc6ec', 'The bob moves fastest at the centre', 'C', false, 2),
('a1c81b5e-d4d1-5abd-aeb3-44c72399c9b4', 'eeae7d42-d98e-592a-be19-213c0adbc6ec', 'The displacement–time graph is sinusoidal', 'D', false, 3),
('a255e365-a7ac-5a88-adbe-141cdaab7479', 'fe6f2114-f7f6-5152-b017-88e9d7a3d7cb', '18 Hz', 'A', false, 0),
('3b5ab96a-ac93-5ccc-a3d9-173a3acbc245', 'fe6f2114-f7f6-5152-b017-88e9d7a3d7cb', '0.60 Hz', 'B', false, 1),
('250cf4be-2a1d-5b8a-b17a-07014d9e5d73', 'fe6f2114-f7f6-5152-b017-88e9d7a3d7cb', '1.7 Hz', 'C', true, 2),
('9f0c3445-77cc-5be4-a7c3-7585b3b3e1ba', 'fe6f2114-f7f6-5152-b017-88e9d7a3d7cb', '540 Hz', 'D', false, 3),
('02c50835-34fa-5530-bb0f-379401f1eb90', 'f92e8bc2-c6cb-59ec-97e2-a7244619e865', 'The displacement–time graph is sinusoidal with a period that does not change with amplitude', 'A', true, 0),
('43069cf2-1e3e-5a3a-aaba-3255b554042a', 'f92e8bc2-c6cb-59ec-97e2-a7244619e865', 'The displacement–time graph is a triangle wave', 'B', false, 1),
('d576e5df-5cdb-57b9-b53b-4d734d29f940', 'f92e8bc2-c6cb-59ec-97e2-a7244619e865', 'The speed is constant throughout', 'C', false, 2),
('96c0ada3-45d7-5007-8e73-e41b396de1f0', 'f92e8bc2-c6cb-59ec-97e2-a7244619e865', 'The period doubles when the amplitude doubles', 'D', false, 3),
('aa5ab124-03de-58ea-8af0-d4e82e666e36', '2e5d7981-1e26-526b-b050-d843c977a17d', '20', 'A', false, 0),
('65bc5459-7d04-55d0-8573-a20579212531', '2e5d7981-1e26-526b-b050-d843c977a17d', '21', 'B', false, 1),
('82eb482e-1c78-5779-af57-003c41828559', '2e5d7981-1e26-526b-b050-d843c977a17d', '10', 'C', false, 2),
('b2265288-6603-5506-b7ad-725030890f53', '2e5d7981-1e26-526b-b050-d843c977a17d', '19', 'D', true, 3),
('7943c175-c6fd-53bd-97aa-ededb0e2ce77', '614a01d1-fa32-59c7-a6f9-8df47b105c31', 'Include it in the mean as it is a real reading', 'A', false, 0),
('5a2266ae-ee76-576d-9509-c7a680cca17d', '614a01d1-fa32-59c7-a6f9-8df47b105c31', 'Treat it as anomalous: repeat that timing and leave it out of the mean if confirmed wrong', 'B', true, 1),
('66fa1213-e454-5e9b-b591-2d1ce6b0207b', '614a01d1-fa32-59c7-a6f9-8df47b105c31', 'Use it alone because it is the largest', 'C', false, 2),
('6d2ba9af-aa75-55ad-8bec-87b59484f696', '614a01d1-fa32-59c7-a6f9-8df47b105c31', 'Halve it', 'D', false, 3),
('5ce33d22-abaf-5321-bde6-f22e5623a4d7', 'cc6001dc-ebc2-517e-a698-6b46afafcccd', 'Using a heavier bob', 'A', false, 0),
('58726ae5-fba5-51b8-9444-a9d1a6601f2b', 'cc6001dc-ebc2-517e-a698-6b46afafcccd', 'Releasing it from a greater height', 'B', false, 1),
('e2d52d12-7cc8-527a-afb2-20ab2a84856d', 'cc6001dc-ebc2-517e-a698-6b46afafcccd', 'Timing more oscillations in each measurement', 'C', true, 2),
('47c71260-013c-57a6-91ad-cca99e60785e', 'cc6001dc-ebc2-517e-a698-6b46afafcccd', 'Timing from the end of the swing instead of the centre', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('3e517679-d067-58ea-a303-718b27e16d83', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 7, 7, 'What is the period of an oscillation?', NULL, 1, 'multiple_choice'::answer_type, 'The time taken for one complete oscillation', NULL, false, NULL, false, NULL, 'T is the time for one full cycle; frequency f = 1/T is the number of cycles per second. Mark scheme (1 mark). B1: C (The time taken for one complete oscillation).', 1),
('1c1acbe1-f139-5cf4-90ab-3c0e86a3519d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 8, 8, 'What is the unit of frequency?', NULL, 1, 'multiple_choice'::answer_type, 'hertz (Hz), equal to s⁻¹', NULL, false, NULL, false, NULL, 'Frequency is the number of oscillations per unit time: 1 Hz = 1 oscillation per second = 1 s⁻¹. Mark scheme (1 mark). B1: A (hertz (Hz), equal to s⁻¹).', 1),
('e26c98a3-ea86-56e4-833f-a23f9b849396', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 9, 9, 'A boat bobs on waves with a frequency of 0.25 Hz. Calculate the period.', NULL, 1, 'numeric'::answer_type, '4', 's', false, NULL, false, NULL, 'T = 1/f = 1 ÷ 0.25 = 4.0 s. Mark scheme (1 mark). A1: T = 4.0 s.', 1),
('188230a4-36dc-5e99-9d01-7c67a6ae0343', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 10, 10, 'A slow-motion video shows a hummingbird''s wing completing each beat in 0.040 s. What is the angular frequency of the beat?', NULL, 1, 'numeric'::answer_type, '157.1', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2π/T = 2π ÷ 0.040 = 157 rad s⁻¹. Mark scheme (2 marks). C1: ω = 2π/T. A1: ω = 157 rad s⁻¹.', 2),
('d6cbf2d5-7295-5501-89d0-afe4bb821255', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 11, 11, 'What is meant by displacement in an oscillation?', NULL, 1, 'multiple_choice'::answer_type, 'The distance from the equilibrium position in a stated direction', NULL, false, NULL, false, NULL, 'Displacement x is measured from the equilibrium position and has a sign (direction). Its maximum value is the amplitude. Mark scheme (1 mark). B1: D (The distance from the equilibrium position in a stated direction).', 1),
('5e56b142-9daf-56e3-89da-d292409becc4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 12, 12, 'Two pendulums swing with the same frequency. One reaches its maximum displacement a quarter of a period after the other. What is their phase difference?', NULL, 1, 'multiple_choice'::answer_type, 'π/2 rad (90°)', NULL, false, NULL, false, NULL, 'A full period corresponds to 2π rad, so a quarter period corresponds to 2π/4 = π/2 rad. Mark scheme (1 mark). B1: B (π/2 rad (90°)).', 1),
('4730137a-b1b0-557c-b58e-fc1d5cdb8815', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 13, 13, 'Two oscillators of frequency 5.0 Hz are out of step by 0.050 s. Calculate their phase difference in radians.', NULL, 1, 'numeric'::answer_type, '1.571', 'rad', false, NULL, false, NULL, 'phase difference = 2π × Δt/T = 2π × 0.050 × 5.0 = 1.57 rad. Mark scheme (2 marks). C1: φ = 2πΔt/T. A1: φ = 1.57 rad.', 2),
('7c8e043d-7c08-5627-975e-e246381e981b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 14, 14, 'Two identical masses on springs oscillate in antiphase. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'When one is at its highest point, the other is at its lowest point', NULL, false, NULL, false, NULL, 'Antiphase means a phase difference of π rad: one is at +A when the other is at −A. Mark scheme (1 mark). B1: C (When one is at its highest point, the other is at its lowest point).', 1),
('791c3584-63e7-5c4c-a75b-18c6705bfecc', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 15, 15, 'A spinning wheel has a valve that goes up and down 3.5 times per second. Calculate the period and the angular frequency of this vertical oscillation. Give the angular frequency.', NULL, 1, 'numeric'::answer_type, '21.99', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2πf = 2π × 3.5 = 22.0 rad s⁻¹ (T = 1/3.5 = 0.29 s). Mark scheme (2 marks). C1: ω = 2πf. A1: ω = 22.0 rad s⁻¹.', 2),
('d993274a-9481-5ebb-8295-7e7edbd8e8fc', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 16, 16, 'An oscillation has angular frequency 50 rad s⁻¹. Calculate its period.', NULL, 1, 'numeric'::answer_type, '0.1257', 's', false, NULL, false, NULL, 'T = 2π/ω = 2π ÷ 50 = 0.126 s. Mark scheme (2 marks). C1: T = 2π/ω. A1: T = 0.126 s.', 2),
('c9c6738d-d4bc-5cd5-82cb-ce38ff85b0cc', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 17, 17, 'Which quantity is the maximum displacement of an oscillating object from its equilibrium position?', NULL, 1, 'multiple_choice'::answer_type, 'Amplitude', NULL, false, NULL, false, NULL, 'The amplitude is the maximum displacement; the peak-to-peak distance is twice the amplitude. Mark scheme (1 mark). B1: A (Amplitude).', 1),
('a0256289-436b-5b70-af49-daa460369589', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 18, 18, 'Two oscillations have a phase difference of 2π rad. How do they compare?', NULL, 1, 'multiple_choice'::answer_type, 'They are in phase', NULL, false, NULL, false, NULL, '2π rad is one whole cycle, so the two are exactly in step: in phase. Mark scheme (1 mark). B1: D (They are in phase).', 1),
('c0df6d0f-da9e-5b42-aaa1-28def66643ea', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 19, 19, 'Express a phase difference of 135° in radians.', NULL, 1, 'numeric'::answer_type, '2.356', 'rad', false, NULL, false, NULL, 'φ = 135 × π ÷ 180 = 2.36 rad (3π/4). Mark scheme (2 marks). C1: × π/180. A1: φ = 2.36 rad.', 2),
('974d40ec-286e-5894-a83f-ad9bb1a8b7a4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 20, 20, 'An electrical signal on an oscilloscope repeats every 2.5 ms. What is its frequency?', NULL, 1, 'numeric'::answer_type, '400', 'Hz', false, NULL, false, NULL, 'f = 1/T = 1 ÷ 2.5 × 10⁻³ = 400 Hz. Mark scheme (1 mark). A1: f = 400 Hz.', 1),
('8413c6b2-c6ee-5982-90ee-bd11dc269fb1', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 21, 21, 'A swing has a period of 3.0 s. A second swing starts 1.5 s later and has the same period. What is their phase difference?', NULL, 1, 'multiple_choice'::answer_type, 'π rad', NULL, false, NULL, false, NULL, '1.5 s is half a period, which corresponds to π rad. Mark scheme (1 mark). B1: B (π rad).', 1),
('32618998-2b91-5534-94e9-11dc733fcbd8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 22, 22, 'Two waves arriving at a point are 0.30 of a cycle out of step. Calculate their phase difference in degrees.', NULL, 1, 'numeric'::answer_type, '108', '°', false, NULL, false, NULL, 'phase difference = 0.30 × 360 = 108°. Mark scheme (2 marks). C1: fraction × 360°. A1: φ = 108°.', 2),
('b1a27053-5a07-546c-8f20-65c0a27faf52', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 23, 23, 'Two pendulums each of period 1.60 s are released 0.20 s apart. Calculate their phase difference in radians and as a fraction of a cycle. Give the phase difference in radians.', NULL, 2, 'numeric'::answer_type, '0.7854', 'rad', false, NULL, false, NULL, 'Fraction of cycle = 0.20 ÷ 1.60 = 0.125. φ = 0.125 × 2π = 0.785 rad (π/4). Mark scheme (3 marks). C1: fraction = Δt/T. C1: × 2π. A1: φ = 0.785 rad.', 3),
('5f8e5453-1ff2-5bd4-abf1-e3241b734d7c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 24, 24, 'Oscillator P passes through its equilibrium position moving upwards at the instant oscillator Q (same frequency) is at its highest point. What is the phase difference?', NULL, 2, 'multiple_choice'::answer_type, 'π/2 rad, with Q a quarter cycle ahead', NULL, false, NULL, false, NULL, 'Q reached the equilibrium position moving upward a quarter cycle earlier, so Q leads P by π/2 rad. Mark scheme (3 marks). C1: quarter of a cycle. C1: π/2 rad. A1: C (π/2 rad, with Q a quarter cycle ahead).', 3),
('4b6c147f-a857-532a-a2ad-278157023a73', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 25, 25, 'A displacement–time graph of a tuning-fork prong has 12 complete cycles in 25 ms. Calculate (a) the period and (b) the angular frequency. Give only the answer to (b).', NULL, 2, 'numeric'::answer_type, '3016', 'rad s⁻¹', false, NULL, false, NULL, '(a) T = 25 ÷ 12 = 2.08 ms. (b) ω = 2π/T = 2π ÷ 0.002083 = 3020 rad s⁻¹. Mark scheme (3 marks). C1: T = t/N. C1: ω = 2π/T. C1: ms to s.', 3),
('f6dfba69-b24f-5a80-addc-c8f7e15c1780', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 26, 26, 'Two masses oscillate with the same period of 0.80 s and a phase difference of 3π/2 rad. Calculate the time interval between them passing through their equilibrium positions in the same direction.', NULL, 2, 'numeric'::answer_type, '0.6', 's', false, NULL, false, NULL, 'Fraction of cycle = (3π/2) ÷ 2π = 0.75. Δt = 0.75 × 0.80 = 0.60 s (equivalently, one leads the other by 0.20 s). Mark scheme (3 marks). C1: fraction = φ/2π. C1: Δt = fraction × T. A1: Δt = 0.60 s.', 3),
('73b6a2b6-7905-5dc1-baa6-46027747e7fa', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 27, 27, 'A vibrating string has amplitude 2.0 mm and frequency 440 Hz. What total distance does a point on the string travel in one second?', NULL, 2, 'multiple_choice'::answer_type, '3.52 m', NULL, false, NULL, false, NULL, 'In each cycle it travels 4A = 8.0 mm. In one second: 440 × 8.0 mm = 3520 mm = 3.52 m. Mark scheme (3 marks). C1: distance per cycle = 4A. C1: × f. A1: A (3.52 m).', 3),
('5a9c336a-c817-593d-80d7-c680326d40f6', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 28, 28, 'A pendulum has amplitude 5.0 cm and period 2.0 s. Calculate the total distance travelled by the bob in 10 s.', NULL, 2, 'numeric'::answer_type, '1', 'm', false, NULL, false, NULL, 'In 10 s it makes 10 ÷ 2.0 = 5 complete oscillations, each covering 4A = 0.20 m. Distance = 5 × 0.20 = 1.0 m. Mark scheme (3 marks). C1: number of oscillations. C1: 4A per cycle. A1: distance = 1.0 m.', 3),
('ca2aed13-7441-5f09-afa0-82a5ca0a1db4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 29, 29, 'Two oscillators have frequencies of 2.0 Hz and 2.1 Hz and start in phase. After how long are they next in phase again?', NULL, 2, 'multiple_choice'::answer_type, '10 s', NULL, false, NULL, false, NULL, 'The faster one gains 0.1 cycles per second, so it gains one whole cycle (back in phase) after 1 ÷ 0.1 = 10 s. Mark scheme (4 marks). C1: difference in frequency. C1: gain one cycle. C1: t = 1/Δf. A1: D (10 s).', 4),
('659fa18a-f1e4-529a-83b2-6839dcad1f07', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 30, 30, 'A phase difference of 0.75 rad exists between two oscillations of frequency 12 Hz. Calculate the time interval this represents.', NULL, 2, 'numeric'::answer_type, '0.009947', 's', false, NULL, false, NULL, 'Δt = (φ/2π) × T = (0.75 ÷ 2π) × (1 ÷ 12) = 0.00995 s. Mark scheme (3 marks). C1: T = 1/f. C1: Δt = φT/2π. A1: Δt = 0.00995 s.', 3),
('42c6da3b-56ca-5ccf-a9ce-1d0f5baf30d4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 31, 31, 'Which statement about two oscillations with a phase difference of π rad and equal amplitudes is correct?', NULL, 2, 'multiple_choice'::answer_type, 'If they are added (superposed), they cancel completely', NULL, false, NULL, false, NULL, 'At every instant one is +x and the other −x, so the sum is zero: complete cancellation. Mark scheme (3 marks). C1: antiphase. C1: x₁ = −x₂ at every instant. A1: B (If they are added (superposed), they cancel completely).', 3),
('5c21f639-4850-5179-bb84-7fe437951c8b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 32, 32, 'An oscillator obeys x = 0.12 cos(5.0t) in SI units. State (a) the amplitude, (b) the angular frequency, and calculate (c) the period. Give only the answer to (c).', NULL, 2, 'numeric'::answer_type, '1.257', 's', false, NULL, false, NULL, '(a) 0.12 m. (b) 5.0 rad s⁻¹. (c) T = 2π/ω = 2π ÷ 5.0 = 1.26 s. Mark scheme (4 marks). B1: amplitude. B1: ω. C1: T = 2π/ω. A1: T = 1.26 s.', 4),
('0b9194b8-450e-595d-b04a-79c91171298e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 33, 33, 'A tuning fork of frequency 512 Hz vibrates with amplitude 0.40 mm. Calculate the time it takes a prong to move from one extreme position to the other.', NULL, 2, 'numeric'::answer_type, '9.766e-4', 's', false, NULL, false, NULL, 'Extreme to extreme is half a period: t = T/2 = 1 ÷ (2 × 512) = 9.77 × 10⁻⁴ s. Mark scheme (3 marks). C1: T = 1/f. C1: half period. A1: t = 9.77 × 10⁻⁴ s.', 3),
('f9d72a31-728e-5b8a-8f77-c95e60d6929e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 34, 34, 'Two pendulums start swinging together, in phase. Pendulum A has period 1.0 s and B has period 1.2 s. What is their phase relationship at t = 3.0 s?', NULL, 2, 'multiple_choice'::answer_type, 'Antiphase', NULL, false, NULL, false, NULL, 'At 3.0 s, A has made 3 cycles and B has made 2.5. The difference is half a cycle: antiphase. Mark scheme (3 marks). C1: cycles completed by each. C1: difference of ½ cycle. A1: C (Antiphase).', 3),
('8a0d7786-f392-5640-b84a-9a18e00d6817', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 35, 35, 'Two points on a vibrating string are 0.25 cycles out of step. The string vibrates at 200 Hz. Calculate the time difference between them reaching maximum displacement.', NULL, 2, 'numeric'::answer_type, '0.00125', 's', false, NULL, false, NULL, 'Δt = fraction × T = 0.25 × (1 ÷ 200) = 1.25 × 10⁻³ s. Mark scheme (3 marks). C1: T = 1/f. C1: Δt = 0.25T. A1: Δt = 0.00125 s.', 3),
('8319511e-d719-55ce-8d0a-1793d5d8785b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 36, 36, 'An object oscillates with x = 4.0 sin(3πt) cm, with t in s. Calculate its frequency and the first time after t = 0 at which x = 4.0 cm. Give that time.', NULL, 2, 'numeric'::answer_type, '0.1667', 's', false, NULL, false, NULL, 'ω = 3π rad s⁻¹, so f = ω/2π = 1.5 Hz. x = 4.0 cm when sin(3πt) = 1, first at 3πt = π/2, so t = 1 ÷ 6 = 0.167 s. Mark scheme (4 marks). C1: ω = 3π. C1: f = 1.5 Hz. C1: sin = 1 at π/2. A1: t = 0.167 s.', 4),
('a23f89f9-ec5c-5409-89d8-c602d3629503', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 37, 37, 'Which pair of quantities fully specifies the size and timing of a sinusoidal oscillation relative to another of the same frequency?', NULL, 2, 'multiple_choice'::answer_type, 'Amplitude and phase difference', NULL, false, NULL, false, NULL, 'With the frequency known, the amplitude gives the size and the phase difference gives the relative timing. Mark scheme (3 marks). C1: amplitude for size. C1: phase for timing. A1: A (Amplitude and phase difference).', 3),
('69351ece-3cd8-5fec-ad3e-5d619ba881dd', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 38, 38, 'Express a phase difference of 5π/6 rad in degrees, and as a fraction of a cycle. Give the fraction.', NULL, 2, 'numeric'::answer_type, '0.4167', NULL, false, NULL, false, NULL, '5π/6 rad × 180/π = 150°. Fraction = (5π/6) ÷ 2π = 5/12 = 0.417 of a cycle. Mark scheme (3 marks). C1: conversion to degrees. C1: fraction = φ/2π. A1: fraction = 0.417.', 3),
('83822065-9ecd-586b-a7c2-39b9730b98f2', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 39, 39, 'Two oscillations of the same frequency are drawn on the same displacement–time axes. The peaks of B occur 2.0 ms after those of A, and the period is 8.0 ms. Which describes B?', NULL, 2, 'multiple_choice'::answer_type, 'B lags A by π/2 rad', NULL, false, NULL, false, NULL, 'B reaches each peak later, so it lags. 2.0/8.0 = ¼ cycle = π/2 rad. Mark scheme (3 marks). C1: later means lags. C1: ¼ of 2π. A1: D (B lags A by π/2 rad).', 3),
('e76a6fa1-1ba1-50df-a401-13becb35303b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 40, 40, 'A wheel turns at 4.0 rev s⁻¹; the shadow of a peg on its rim (radius 0.15 m) moves back and forth on a wall in simple harmonic motion. Calculate the amplitude, period and angular frequency of the shadow''s motion. Give the angular frequency.', NULL, 2, 'numeric'::answer_type, '25.13', 'rad s⁻¹', false, NULL, false, NULL, 'Amplitude = radius = 0.15 m. T = 1 ÷ 4.0 = 0.25 s. ω = 2πf = 2π × 4.0 = 25.1 rad s⁻¹. Mark scheme (4 marks). B1: amplitude = radius. C1: T = 1/f. C1: ω = 2πf. A1: ω = 25.1 rad s⁻¹.', 4),
('8951d971-2e98-5abd-af1c-413cd69a57d8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 41, 41, 'Two simple pendulums have lengths 1.00 m and 0.81 m. They are released together, in phase. (a) Calculate both periods. (b) Calculate how many oscillations the shorter one makes before they are next in phase. (c) Calculate the time at which this happens. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '18.05', 's', false, NULL, false, NULL, '(a) T₁ = 2π × √(1.00 ÷ 9.81) = 2.01 s, T₂ = 2π × √(0.81 ÷ 9.81) = 1.81 s. (b) T ∝ √L: T₂/T₁ = 0.9, so after 10 swings of the short one the long one has made 9: n = 10. (c) t = 10 × 1.805 = 18.1 s. Mark scheme (5 marks). C1: T = 2π√(L/g). A1: both periods. M1: ratio 0.9 → gains one swing in 10. A1: 10 oscillations. A1: t = 18.1 s.', 5),
('86fdd2f3-8409-5efb-999b-1fe7fe9ccc3a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 42, 42, 'A displacement–time graph shows two oscillations, X and Y, of period 40 ms. X has amplitude 3.0 mm and a maximum at t = 0. Y has amplitude 2.0 mm and a maximum at t = 30 ms. (a) Calculate the phase difference, stating which leads. (b) Write an equation for each in the form x = A cos(ωt + φ). (c) Calculate the displacement of Y at t = 10 ms. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '-2 mm', 'mm', false, NULL, true, NULL, '(a) 30 ms is 0.75 of a cycle: φ = 3π/2 rad, Y lags X (equivalently Y leads X by π/2). (b) ω = 2π/0.040 = 157 rad s⁻¹. X: x = 3.0 cos(ωt) mm. Y: x = 2.0 cos(ω(t − 0.030)) mm. (c) At t = 10 ms, Y is 20 ms (half a period) before its peak: x = 2.0 × cos(−180°) = 2.0 × cos 180° = −2.0 mm (Y is at its most negative displacement). Mark scheme (6 marks). C1: fraction of period. A1: phase difference and which leads. C1: ω = 2π/T. B1: equations. C1: substitution. A1: x = −2.0 mm.', 6),
('0dee361f-4761-5eb2-ad03-c52450746879', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 43, 43, 'A point on the Earth''s Equator is viewed from far above the North Pole. Its shadow on a distant screen (along a line through the Earth''s centre) moves with simple harmonic motion. Earth radius = 6.37 × 10⁶ m, rotation period = 24.0 h. (a) State the amplitude. (b) Calculate the angular frequency. (c) Calculate the maximum speed of the shadow. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '463.2', 'm s⁻¹', false, NULL, false, NULL, '(a) A = 6.37 × 10⁶ m (the radius). (b) ω = 2π/T = 2π ÷ 86400 = 7.27 × 10⁻⁵ rad s⁻¹. (c) v_max = ωA = 7.27 × 10⁻⁵ × 6.37 × 10⁶ = 463 m s⁻¹ (equal to the speed of the point itself). Mark scheme (5 marks). B1: amplitude = radius. C1: ω = 2π/T. A1: ω. C1: v_max = ωA. A1: v_max = 463 m s⁻¹.', 5),
('1e47796e-fde4-5b03-9b25-e17dd17389bf', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 44, 44, 'Two loudspeakers are driven by the same 680 Hz signal. A microphone is 0.25 m further from one speaker than the other. The speed of sound is 340 m s⁻¹. (a) Calculate the wavelength. (b) Calculate the phase difference, in radians, between the two waves at the microphone. (c) State what is heard there and explain. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '3.142', 'rad', false, NULL, false, NULL, '(a) λ = v/f = 340 ÷ 680 = 0.50 m. (b) Path difference 0.25 m is half a wavelength: φ = 2π × 0.25 ÷ 0.50 = 3.14 rad. (c) The waves arrive in antiphase, so they cancel (destructive interference): a quiet point. Mark scheme (6 marks). C1: λ = v/f. A1: λ. C1: φ = 2π × path difference/λ. A1: φ = 3.14 rad. B1: antiphase. B1: quiet / destructive.', 6),
('553628ea-1564-5bac-9c0b-977bbb4d5c69', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 45, 45, 'A car''s wheels are 0.66 m in diameter. The car moves at 14 m s⁻¹. A reflector on the wheel rim moves up and down. (a) Calculate the frequency of this vertical oscillation. (b) State its amplitude. (c) Calculate the angular frequency. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '6.752', 'Hz', false, NULL, false, NULL, '(a) One cycle per revolution: f = v/(2πr) = 14 ÷ (π × 0.66) = 6.75 Hz. (b) A = r = 0.33 m. (c) ω = 2πf = 42.4 rad s⁻¹. Mark scheme (5 marks). C1: one oscillation per revolution. C1: f = v/(2πr). A1: f = 6.75 Hz. B1: A = 0.33 m. B1: ω = 2πf.', 5),
('4f8b9dfb-6ae6-50b9-9c00-c8fc89dc8fd0', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 46, 46, 'Oscillator P obeys x_P = 5.0 sin(4πt) cm and Q obeys x_Q = 5.0 sin(4πt + π/3) cm. (a) State their common frequency. (b) State the phase difference and which leads. (c) Calculate the time interval between P and Q reaching their maximum displacement. (d) Calculate x_Q at the instant P is at its maximum. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '2.5 cm', 'cm', false, NULL, false, NULL, '(a) ω = 4π rad s⁻¹, so f = 2.0 Hz. (b) π/3 rad, Q leads. (c) Δt = (π/3) ÷ (4π) = 1/12 = 0.083 s. (d) P is at its maximum when 4πt = π/2, so x_Q = 5.0 × sin(90° + 60°) = 5.0 × sin 150° = 2.50 cm. Mark scheme (6 marks). B1: f = 2.0 Hz. B1: π/3, Q leads. C1: Δt = φ/ω. A1: 0.083 s. C1: phase of Q at P maximum. A1: x_Q = 2.50 cm.', 6),
('7917cdb3-ff8b-52e9-8a4a-7fa3e57834f8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 47, 47, 'Two children on identical swings are pushed so that they swing with the same period, 3.0 s, but child B passes the lowest point 0.50 s after child A. (a) Calculate the phase difference in radians. (b) State the phase difference in degrees. (c) Calculate how much later B would need to be pushed for them to be in antiphase. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '1.047', 'rad', false, NULL, false, NULL, '(a) φ = 2πΔt/T = 2π × 0.50 ÷ 3.0 = 1.05 rad. (b) 0.50 ÷ 3.0 × 360 = 60°. (c) Antiphase needs Δt = T/2 = 1.5 s. Mark scheme (5 marks). C1: φ = 2πΔt/T. A1: φ = 1.05 rad. B1: 60°. C1: T/2 for antiphase. A1: 1.5 s.', 5),
('222cdcbb-25b6-5b25-b1c2-bab4ff1f93e5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 48, 48, 'A wheel of radius 0.20 m spins at 2.0 rev s⁻¹. A peg on its rim casts a shadow on a vertical wall from a horizontal beam of light, and the shadow moves up and down. (a) Explain why the shadow moves with s.h.m. (b) Calculate the amplitude, period and maximum speed of the shadow. (c) A second peg is 90° further round the rim. State the phase difference between the two shadows. Give only the maximum speed in (b).', NULL, 3, 'numeric'::answer_type, '2.513', 'm s⁻¹', false, NULL, false, NULL, '(a) The shadow''s height is r sin θ with θ = ωt increasing uniformly: y = r sin ωt, which is s.h.m. (b) A = 0.20 m, T = 0.50 s, v_max = ωA = 2π × 2.0 × 0.20 = 2.51 m s⁻¹. (c) π/2 rad. Mark scheme (6 marks). M1: y = r sin ωt. B1: A and T. C1: v_max = ωA. A1: v_max = 2.51 m s⁻¹. B1: π/2 rad. B1: equals speed of peg.', 6),
('1adc927f-d931-5126-abae-4e93b211d63e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 49, 49, 'A displacement–time graph shows two oscillations of the same frequency 25 Hz. Their peaks are separated by 12 ms. (a) Calculate the period. (b) Calculate the phase difference in radians. (c) Explain why a separation of 52 ms would give the same phase difference. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.885', 'rad', false, NULL, false, NULL, '(a) T = 1/f = 0.040 s = 40 ms. (b) φ = 2π × 12 ÷ 40 = 1.88 rad. (c) 52 ms = 40 + 12 ms: one extra whole period does not change the phase difference. Mark scheme (5 marks). A1: T = 40 ms. C1: φ = 2πΔt/T. A1: φ = 1.88 rad. B1: extra whole period. B1: phase repeats every 2π.', 5),
('3a9f79e2-19c0-5358-816a-ae724951f0fd', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 50, 50, 'A guitar string vibrates at 196 Hz with amplitude 1.5 mm. (a) Calculate the period. (b) Calculate the distance a point at the centre of the string travels in 2.0 s. (c) Calculate the average speed of that point. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.352', 'm', false, NULL, false, NULL, '(a) T = 1 ÷ 196 = 0.00510 s. (b) Distance per cycle = 4A = 6.0 mm. Cycles in 2.0 s = 196 × 2.0 = 392. Distance = 392 × 0.0060 = 2.35 m. (c) average speed = 2.352 ÷ 2.0 = 1.18 m s⁻¹. Mark scheme (6 marks). A1: T. B1: 4A per cycle. C1: number of cycles. A1: distance. B1: average speed. A1: distance = 2.35 m.', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('87d90de6-32ef-51ed-8c55-043420b3b1e3', '3e517679-d067-58ea-a303-718b27e16d83', 'The number of oscillations per second', 'A', false, 0),
('af716693-ba81-5bdd-98b2-0bc4fa3158ba', '3e517679-d067-58ea-a303-718b27e16d83', 'The maximum displacement from equilibrium', 'B', false, 1),
('68b0f4a1-bc06-5c65-9dd6-8b9ec2c73d6a', '3e517679-d067-58ea-a303-718b27e16d83', 'The time taken for one complete oscillation', 'C', true, 2),
('8b76229a-da86-5b46-9463-176731f6123a', '3e517679-d067-58ea-a303-718b27e16d83', 'The time from the centre to one end', 'D', false, 3),
('15727321-8cf8-5241-9c11-b70c3fff557e', '1c1acbe1-f139-5cf4-90ab-3c0e86a3519d', 'hertz (Hz), equal to s⁻¹', 'A', true, 0),
('2e62d942-4e10-502e-9bc1-a240721666a9', '1c1acbe1-f139-5cf4-90ab-3c0e86a3519d', 'seconds (s)', 'B', false, 1),
('bf41a117-a426-5547-a731-824efdba242c', '1c1acbe1-f139-5cf4-90ab-3c0e86a3519d', 'rad s⁻²', 'C', false, 2),
('5aaec867-a857-50af-a6aa-7263377cde7b', '1c1acbe1-f139-5cf4-90ab-3c0e86a3519d', 'metres (m)', 'D', false, 3),
('602ac92c-7e5e-5828-9ec1-a6c8865e355b', 'd6cbf2d5-7295-5501-89d0-afe4bb821255', 'The total distance travelled', 'A', false, 0),
('38fa5f80-fd0f-55a3-8da4-b7056c9e75f9', 'd6cbf2d5-7295-5501-89d0-afe4bb821255', 'The maximum distance from equilibrium', 'B', false, 1),
('ae21ca3e-4440-58ae-8983-185d616cea0e', 'd6cbf2d5-7295-5501-89d0-afe4bb821255', 'The distance between the two ends of the motion', 'C', false, 2),
('11781eed-9223-5c97-b803-306b4666ce24', 'd6cbf2d5-7295-5501-89d0-afe4bb821255', 'The distance from the equilibrium position in a stated direction', 'D', true, 3),
('9e203d50-c452-5b36-bcfd-ac86e8f4abe4', '5e56b142-9daf-56e3-89da-d292409becc4', 'π rad (180°)', 'A', false, 0),
('52dc1c67-92ae-5d43-95d8-25f663145a89', '5e56b142-9daf-56e3-89da-d292409becc4', 'π/2 rad (90°)', 'B', true, 1),
('4a395bcc-accc-524a-b9f9-0ebd60465e2a', '5e56b142-9daf-56e3-89da-d292409becc4', 'π/4 rad (45°)', 'C', false, 2),
