('c067a078-238f-5ffd-8115-c6a5f76bb2cb', '42c6da3b-56ca-5ccf-a9ce-1d0f5baf30d4', 'They reach maximum displacement at the same time', 'A', false, 0),
('40243c48-1c65-51d1-8dcd-f9d3c8d6acff', '42c6da3b-56ca-5ccf-a9ce-1d0f5baf30d4', 'If they are added (superposed), they cancel completely', 'B', true, 1),
