INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('e44fcb3d-89fd-5e87-967d-2b68f3ab4ed2', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 6, 6, 'Which equation defines simple harmonic motion?', NULL, 1, 'multiple_choice'::answer_type, 'a = −ω²x', NULL, false, NULL, false, NULL, 'S.h.m.: the acceleration is proportional to the displacement from a fixed point and always directed towards that point. Mark scheme (1 mark). B1: C (a = −ω²x).', 1),
('1a251721-d606-5ae1-8b9b-8735b7f33354', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 7, 7, 'In s.h.m., what does the minus sign in a = −ω²x tell us?', NULL, 1, 'multiple_choice'::answer_type, 'The acceleration is always directed towards the equilibrium position', NULL, false, NULL, false, NULL, 'The acceleration is opposite to the displacement: towards the centre on both sides. Mark scheme (1 mark). B1: A (The acceleration is always directed towards the equilibrium position).', 1),
('9f6f86c6-0847-5061-9f60-fde20cd532f3', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 8, 8, 'At which point in s.h.m. is the speed greatest?', NULL, 1, 'multiple_choice'::answer_type, 'At the equilibrium position', NULL, false, NULL, false, NULL, 'At equilibrium the restoring force is zero and all the energy is kinetic: maximum speed. Mark scheme (1 mark). B1: D (At the equilibrium position).', 1),
('ae778f52-b8a2-5b9d-b944-0e6f62c11d9c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 9, 9, 'A body moves with s.h.m. of angular frequency 6.0 rad s⁻¹ and amplitude 0.050 m. Calculate its maximum speed.', NULL, 1, 'numeric'::answer_type, '0.3', 'm s⁻¹', false, NULL, false, NULL, 'v_max = ωA = 6.0 × 0.050 = 0.30 m s⁻¹. Mark scheme (2 marks). C1: v_max = ωx₀. A1: v_max = 0.30 m s⁻¹.', 2),
('873c34be-70f4-5542-8749-2163db3f3e4f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 10, 10, 'The tip of a vibrating cantilever moves with s.h.m. at 12 rad s⁻¹ through an amplitude of 2.5 cm. Find the greatest acceleration of the tip.', NULL, 1, 'numeric'::answer_type, '3.6', 'm s⁻²', false, NULL, false, NULL, 'a_max = ω²A = 12² × 0.025 = 3.6 m s⁻². Mark scheme (2 marks). C1: a_max = ω²x₀. A1: a_max = 3.6 m s⁻².', 2),
('8bf7e858-3860-54ab-abc0-9f8072c98fe8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 11, 11, 'The acceleration of an oscillating object is a = −250x in SI units. Calculate its angular frequency.', NULL, 1, 'numeric'::answer_type, '15.81', 'rad s⁻¹', false, NULL, false, NULL, 'a = −ω²x, so ω² = 250 and ω = √250 = 15.8 rad s⁻¹. Mark scheme (2 marks). C1: compare with a = −ω²x. A1: ω = 15.8 rad s⁻¹.', 2),
('090e931f-1d8e-5d7b-8d25-79d9a006d817', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 12, 12, 'Which of these motions is simple harmonic (to a good approximation)?', NULL, 1, 'multiple_choice'::answer_type, 'A mass bouncing gently on a spring', NULL, false, NULL, false, NULL, 'A mass on a spring has a restoring force proportional to displacement (F = −kx), so a ∝ −x. Mark scheme (1 mark). B1: B (A mass bouncing gently on a spring).', 1),
('43adc659-631e-57f5-a0b3-d2a1b5eadd7d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 13, 13, 'An object in s.h.m. has ω = 4.0 rad s⁻¹. Calculate its acceleration when its displacement is +0.15 m.', NULL, 1, 'numeric'::answer_type, '-2.4', 'm s⁻²', false, NULL, true, NULL, 'a = −ω²x = −4.0² × 0.15 = −2.4 m s⁻². Mark scheme (2 marks). C1: a = −ω²x. A1: a = −2.4 m s⁻².', 2),
('b7cef488-68db-504f-8b03-49ce3201eb22', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 14, 14, 'At maximum displacement in s.h.m., which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'The speed is zero and the acceleration is maximum', NULL, false, NULL, false, NULL, 'At the extremes the object momentarily stops; the restoring force (and acceleration) is greatest there. Mark scheme (1 mark). B1: C (The speed is zero and the acceleration is maximum).', 1),
('60f64795-f0b7-5a43-b2f3-7af9504e32e7', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 15, 15, 'For a mass on a spring, which force provides the restoring force?', NULL, 1, 'multiple_choice'::answer_type, 'The resultant of the spring tension and the weight', NULL, false, NULL, false, NULL, 'Displaced from equilibrium, the spring force and weight no longer balance; their resultant, −kx, points back to equilibrium. Mark scheme (1 mark). B1: A (The resultant of the spring tension and the weight).', 1),
('13580ef8-93df-5e2c-b679-723ed2d6fde8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 16, 16, 'A diaphragm vibrates with s.h.m. of frequency 500 Hz and amplitude 0.10 mm. Calculate its maximum speed.', NULL, 1, 'numeric'::answer_type, '0.3142', 'm s⁻¹', false, NULL, false, NULL, 'v_max = ωx₀ = 2π × 500 × 1.0 × 10⁻⁴ = 0.314 m s⁻¹. Mark scheme (2 marks). C1: ω = 2πf, v = ωx₀. A1: v_max = 0.314 m s⁻¹.', 2),
('c5d28598-342b-520d-a0ea-7bf5bb239bc1', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 17, 17, 'The amplitude of an s.h.m. is doubled without changing the period. What happens to the maximum speed?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'v_max = ωx₀ with ω fixed, so v_max ∝ x₀. Mark scheme (1 mark). B1: D (It doubles).', 1),
('9cebfe1d-2283-5875-8124-8e60e8ec0c08', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 18, 18, 'An object oscillates with s.h.m. with maximum speed 0.60 m s⁻¹ and amplitude 0.040 m. Calculate ω.', NULL, 1, 'numeric'::answer_type, '15', 'rad s⁻¹', false, NULL, false, NULL, 'ω = v_max/x₀ = 0.60 ÷ 0.040 = 15 rad s⁻¹. Mark scheme (2 marks). C1: v_max = ωx₀. A1: ω = 15 rad s⁻¹.', 2),
('d291110b-42e2-568b-88aa-df1ded96b7ad', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 19, 19, 'In s.h.m. the acceleration is zero. Where is the object?', NULL, 1, 'multiple_choice'::answer_type, 'At the equilibrium position', NULL, false, NULL, false, NULL, 'a = −ω²x is zero only when x = 0. Mark scheme (1 mark). B1: B (At the equilibrium position).', 1),
('837192a1-8b44-5901-bd2f-64d014587c09', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 20, 20, 'A mass on a spring has ω = 8.0 rad s⁻¹. What is its acceleration when it is 3.0 cm below the equilibrium position (take up as positive)?', NULL, 1, 'numeric'::answer_type, '1.92', 'm s⁻²', false, NULL, true, NULL, 'x = −0.030 m. a = −ω²x = −64 × (−0.030) = +1.92 m s⁻² (upwards). Mark scheme (2 marks). C1: a = −ω²x with sign. A1: a = 1.92 m s⁻².', 2),
('56ca3200-6d7d-5fae-b062-19a4c74f4fee', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 21, 21, 'Which graph of acceleration a against displacement x represents s.h.m.?', NULL, 1, 'multiple_choice'::answer_type, 'A straight line through the origin with negative gradient', NULL, false, NULL, false, NULL, 'a = −ω²x: a straight line through the origin with gradient −ω². Mark scheme (1 mark). B1: C (A straight line through the origin with negative gradient).', 1),
('96c8ce02-c799-5c95-b7aa-ebc24f51eb80', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 22, 22, 'A graph of acceleration against displacement for an oscillator is a straight line through the origin, passing through (0.040 m, −2.5 m s⁻²). Calculate the frequency of the oscillation.', NULL, 2, 'numeric'::answer_type, '1.258', 'Hz', false, NULL, false, NULL, 'Gradient = −ω² = −2.5 ÷ 0.040 = −62.5 s⁻². ω = √62.5 = 7.91 rad s⁻¹. f = ω/2π = 7.906 ÷ 2π = 1.26 Hz. Mark scheme (3 marks). C1: gradient = −ω². C1: ω. C1: f = ω/2π.', 3),
('d2cbcb8d-2d76-5bd3-838c-de209bc2cf13', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 23, 23, 'A mass on a spring oscillates with period 0.40 s and amplitude 3.0 cm. Calculate its speed when its displacement is 1.8 cm.', NULL, 2, 'numeric'::answer_type, '0.377', 'm s⁻¹', false, NULL, false, NULL, 'ω = 2π/T = 2π ÷ 0.40 = 15.7 rad s⁻¹. v = ω√(x₀² − x²) = 15.7 × √(0.030² − 0.018²) = 0.377 m s⁻¹. Mark scheme (3 marks). C1: ω = 2π/T. C1: v = ω√(x₀² − x²). C1: lengths in m.', 3),
('eaa7351f-008b-5536-9718-01bea32aac88', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 24, 24, 'A piston in an engine moves with approximately s.h.m. of amplitude 4.5 cm at 3000 rev min⁻¹. Calculate the maximum acceleration of the piston.', NULL, 2, 'numeric'::answer_type, '4441', 'm s⁻²', false, NULL, false, NULL, 'f = 3000 ÷ 60 = 50 Hz, ω = 2π × 50 = 314 rad s⁻¹. a_max = ω²x₀ = (314)² × 0.045 = 4440 m s⁻². Mark scheme (4 marks). C1: f from rev min⁻¹. C1: ω = 2πf. C1: a_max = ω²x₀. A1: a_max = 4440 m s⁻².', 4),
('3139979a-98e8-539e-8c56-ae9b1103b2ac', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 25, 25, 'A student says: "In s.h.m. the acceleration is constant, because the motion repeats regularly." What is wrong?', NULL, 2, 'multiple_choice'::answer_type, 'The acceleration changes all the time: it is proportional to the displacement, so it varies from zero to its maximum value', NULL, false, NULL, false, NULL, 'a = −ω²x changes with x throughout the cycle; only ω (and so the period) is constant. Mark scheme (3 marks). C1: a ∝ −x. C1: varies through the cycle. A1: A (The acceleration changes all the time: it is proportional to the displacement, so it varies from zero to its maximum value).', 3),
('215c25ec-776f-5f65-b625-36740555f505', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 26, 26, 'The cone of a loudspeaker vibrates with frequency 2.0 kHz. Its maximum acceleration is 790 m s⁻². Calculate the amplitude of its vibration.', NULL, 2, 'numeric'::answer_type, '5.003e-6', 'm', false, NULL, false, NULL, 'ω = 2π × 2000 = 1.26 × 10⁴ rad s⁻¹. x₀ = a_max/ω² = 790 ÷ (1.26 × 10⁴)² = 5.00 × 10⁻⁶ m. Mark scheme (3 marks). C1: ω = 2πf. C1: x₀ = a_max/ω². C1: kHz to Hz.', 3),
('75e15945-e191-58fa-9df8-8a7af6db4cc9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 27, 27, 'A body moves with s.h.m. At which displacement is its speed half its maximum speed?', NULL, 2, 'multiple_choice'::answer_type, '√3/2 of the amplitude, about 0.87x₀', NULL, false, NULL, false, NULL, 'v = ω√(x₀² − x²) = ½ωx₀ gives x₀² − x² = x₀²/4, so x = (√3/2)x₀ ≈ 0.87x₀. Mark scheme (3 marks). C1: v = ω√(x₀² − x²). C1: solve for x. A1: D (√3/2 of the amplitude, about 0.87x₀).', 3),
('30c57749-7b80-5fd8-8fb0-ccdb6b1df7f3', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 28, 28, 'For a simple pendulum, the restoring acceleration is a = −(g/L)x for small displacements. Calculate the angular frequency of a pendulum of length 2.5 m. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '1.981', 'rad s⁻¹', false, NULL, false, NULL, 'ω² = g/L = 9.81 ÷ 2.5 = 3.92 s⁻², ω = √3.924 = 1.98 rad s⁻¹. Mark scheme (3 marks). C1: ω² = g/L. C1: square root. A1: ω = 1.98 rad s⁻¹.', 3),
('bab66dae-62c8-509a-b7aa-536456ae1d02', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 29, 29, 'An oscillator has maximum speed 1.2 m s⁻¹ and maximum acceleration 18 m s⁻². Calculate its amplitude and angular frequency. Give the amplitude.', NULL, 2, 'numeric'::answer_type, '0.08', 'm', false, NULL, false, NULL, 'a_max/v_max = ω²x₀/(ωx₀) = ω, so ω = 18 ÷ 1.2 = 15 rad s⁻¹. x₀ = v_max/ω = 1.2 ÷ 15 = 0.0800 m. Mark scheme (4 marks). C1: ω = a_max/v_max. C1: x₀ = v_max/ω. C1: substitution. A1: x₀ = 0.0800 m.', 4),
('f24895a8-389f-5b21-9de2-f41980e39cb2', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 30, 30, 'Which condition must be satisfied for an oscillation to be simple harmonic?', NULL, 2, 'multiple_choice'::answer_type, 'The restoring force must be proportional to the displacement and directed towards equilibrium', NULL, false, NULL, false, NULL, 'F = −kx (and so a = −ω²x) is the condition. Mark scheme (3 marks). C1: F ∝ x. C1: towards equilibrium. A1: B (The restoring force must be proportional to the displacement and directed towards equilibrium).', 3),
('dda11273-8023-5835-8349-87f0cea689b0', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 31, 31, 'A mass on a spring (k = 120 N m⁻¹) oscillates with amplitude 5.0 cm. Its mass is 0.30 kg. Calculate the maximum restoring force and the maximum acceleration. Give the acceleration.', NULL, 2, 'numeric'::answer_type, '20', 'm s⁻²', false, NULL, false, NULL, 'F_max = kx₀ = 120 × 0.050 = 6.0 N. a_max = F/m = 6.0 ÷ 0.30 = 20 m s⁻². Mark scheme (3 marks). C1: F = kx₀. C1: a = F/m. A1: a_max = 20 m s⁻².', 3),
('d42d506f-5ec5-58d7-9096-4016eba5a2c0', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 32, 32, 'A ball rolls back and forth in a curved bowl of radius R. For small displacements, it moves with s.h.m. of ω² = g/R (like a pendulum). If R is quadrupled, what happens to the period?', NULL, 2, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'T = 2π/ω = 2π√(R/g) ∝ √R: √4 = 2. Mark scheme (3 marks). C1: T ∝ √R. C1: factor 2. A1: C (It doubles).', 3),
('4f37f7f7-9a05-5e41-a08c-820be2a7f045', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 33, 33, 'A ship rolls with s.h.m. of period 12 s. The tip of its mast swings with an amplitude of 3.0 m. Calculate the maximum speed of the mast tip.', NULL, 2, 'numeric'::answer_type, '1.571', 'm s⁻¹', false, NULL, false, NULL, 'v_max = ωx₀ = (2π ÷ 12) × 3.0 = 1.57 m s⁻¹. Mark scheme (3 marks). C1: ω = 2π/T. C1: v_max = ωx₀. A1: v_max = 1.57 m s⁻¹.', 3),
('a8f64708-d52b-5593-9f7d-5c1b21c46883', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 34, 34, 'An object in s.h.m. has amplitude 8.0 cm and period 1.6 s. Calculate its acceleration when it is 5.0 cm from equilibrium.', NULL, 2, 'numeric'::answer_type, '0.7711', 'm s⁻²', false, NULL, false, NULL, 'ω = 2π ÷ 1.6 = 3.93 rad s⁻¹. |a| = ω²x = (3.93)² × 0.050 = 0.771 m s⁻², towards equilibrium. Mark scheme (4 marks). C1: ω = 2π/T. C1: a = −ω²x. B1: direction. A1: |a| = 0.771 m s⁻².', 4),
('2bf960be-caed-5350-bc53-0a3fd978d570', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 35, 35, 'A test tube weighted at the bottom floats upright in water and bobs up and down. Why can its motion be simple harmonic?', NULL, 2, 'multiple_choice'::answer_type, 'The extra upthrust when it is pushed down is proportional to how far it is pushed down', NULL, false, NULL, false, NULL, 'Pushed down by x, it displaces extra water of volume Ax, so the restoring force ρgAx ∝ x. Mark scheme (3 marks). C1: extra upthrust ∝ depth. C1: F ∝ −x. A1: A (The extra upthrust when it is pushed down is proportional to how far it is pushed down).', 3),
('00b33210-f221-5b1b-9ef6-1fee161ccb7b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 36, 36, 'For a floating test tube of cross-sectional area 2.0 cm² and mass 0.040 kg, the restoring force is ρgAx. Calculate ω for its bobbing. Density of water = 1000 kg m⁻³. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '7.004', 'rad s⁻¹', false, NULL, false, NULL, 'k = ρgA = 1000 × 9.81 × 2.0 × 10⁻⁴ = 1.96 N m⁻¹. ω = √(k/m) = √(1.962 ÷ 0.040) = 7.00 rad s⁻¹. Mark scheme (3 marks). C1: k = ρgA. C1: area in m². C1: ω = √(k/m).', 3),
('838d526c-ee4f-5f4b-a362-6a6f49e233fa', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 37, 37, 'Which quantity is NOT the same at the two extreme positions of a simple harmonic oscillation?', NULL, 2, 'multiple_choice'::answer_type, 'The direction of the acceleration', NULL, false, NULL, false, NULL, 'At +x₀ the acceleration points in the −x direction; at −x₀ it points in the +x direction. Mark scheme (3 marks). C1: magnitudes equal. C1: directions opposite. A1: D (The direction of the acceleration).', 3),
('96361861-0c87-5e6d-aa50-4dbbdfb88f62', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 38, 38, 'An oscillating body has a = −49x. It passes through equilibrium at 0.35 m s⁻¹. Calculate its amplitude and the time from equilibrium to maximum displacement. Give the time.', NULL, 2, 'numeric'::answer_type, '0.2244', 's', false, NULL, false, NULL, 'ω = √49 = 7.0 rad s⁻¹. x₀ = v_max/ω = 0.35 ÷ 7.0 = 0.050 m. t = T/4 = (2π ÷ 7.0) ÷ 4 = 0.224 s. Mark scheme (4 marks). C1: ω = 7.0. C1: x₀ = v/ω. C1: quarter period. A1: t = 0.224 s.', 4),
('7e587efb-e1c5-5d25-88b8-d7f4317fcb49', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 39, 39, 'A 0.20 kg mass on a spring of constant 80 N m⁻¹ is pulled 4.0 cm below equilibrium and released. (a) Show that the motion is s.h.m. and find ω. (b) Calculate the maximum speed. (c) Calculate the speed and acceleration when the mass is 2.0 cm above equilibrium. Give only the speed in (c).', NULL, 3, 'numeric'::answer_type, '0.6928', 'm s⁻¹', false, NULL, false, NULL, '(a) F = −kx, so a = −(k/m)x: s.h.m. with ω = √(k/m) = √(80 ÷ 0.20) = 20 rad s⁻¹. (b) v_max = ωx₀ = 20 × 0.040 = 0.80 m s⁻¹. (c) v = ω√(x₀² − x²) = 20 × √(0.040² − 0.020²) = 0.693 m s⁻¹, a = −ω²x = −400 × 0.020 = −8.0 m s⁻² (downwards). Mark scheme (6 marks). M1: F = −kx gives a ∝ −x. A1: ω = 20 rad s⁻¹. A1: v_max. C1: v = ω√(x₀² − x²). A1: v = 0.693 m s⁻¹. B1: a = −8.0 m s⁻².', 6),
('ad413ab6-b73b-5d43-ae1a-6b97d75a470b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 40, 40, 'A platform vibrates vertically with s.h.m. of frequency 5.0 Hz. A small coin rests on it. (a) Explain why the coin leaves the platform if the amplitude is too large. (b) Calculate the maximum amplitude for which the coin stays in contact. (c) State where in the cycle the coin first loses contact. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.00994', 'm', false, NULL, false, NULL, '(a) At the top the platform accelerates downwards at ω²x₀. If this exceeds g, the coin (which can only fall at g) is left behind. (b) ω²x₀ = g: x₀ = 9.81 ÷ (2π × 5.0)² = 0.00994 m. (c) At the top of the motion, where the downward acceleration is greatest. Mark scheme (5 marks). B1: downward acceleration exceeds g. M1: ω²x₀ = g. C1: ω = 2πf. A1: x₀ = 0.00994 m. B1: at the top.', 5),
('8daf3537-126d-5e48-b744-13d375692d9e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 41, 41, 'A U-tube contains a column of liquid of total length 0.60 m. When displaced and released the liquid oscillates with a = −(2g/L)x. (a) Calculate the period. (b) The liquid surface is displaced by 2.0 cm. Calculate the maximum speed of the liquid. (c) Explain why the period does not depend on the density of the liquid. Give only the answer to (a). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '1.099', 's', false, NULL, false, NULL, '(a) ω² = 2g/L = 2 × 9.81 ÷ 0.60 = 32.7 s⁻², ω = 5.72 rad s⁻¹, T = 2π/ω = 2π ÷ 5.718 = 1.10 s. (b) v_max = ωx₀ = 5.718 × 0.020 = 0.114 m s⁻¹. (c) Both the restoring force (weight of the extra column) and the inertia (mass of all the liquid) are proportional to density, which cancels. Mark scheme (6 marks). C1: ω² = 2g/L. A1: ω. A1: T = 1.10 s. C1: v_max = ωx₀. B1: density cancels. B1: both ∝ ρ.', 6),
('be8e98f7-9aef-5da4-8aaf-ab55c8ce525f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 42, 42, 'A body in s.h.m. has speed 0.30 m s⁻¹ at displacement 4.0 cm and speed 0.40 m s⁻¹ at displacement 3.0 cm. (a) Write two equations using v² = ω²(x₀² − x²). (b) Solve them to find ω. (c) Calculate the amplitude. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.05', 'm', false, NULL, false, NULL, '(a) 0.30² = ω²(x₀² − 0.040²) and 0.40² = ω²(x₀² − 0.030²). (b) Subtract: 0.16 − 0.09 = ω²(0.040² − 0.030²), so ω² = 0.07 ÷ 0.0007 = 100 and ω = 10 rad s⁻¹. (c) x₀² = 0.09 ÷ 100 + 0.040² = 0.0025, x₀ = √0.0025 = 0.050 m. Mark scheme (5 marks). B1: both equations. M1: subtraction to eliminate x₀. A1: ω = 10 rad s⁻¹. C1: substitution back. A1: x₀ = 0.050 m.', 5),
('5703f409-3c6a-5dba-8c40-e465b2fc8cce', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 43, 43, 'A ball bearing of mass 20 g rolls in a curved track of radius of curvature 0.40 m. For small oscillations a = −(5g/7R)x (allowing for rolling). (a) Calculate the period. (b) Compare it with a simple pendulum of length 0.40 m. (c) Explain physically why rolling makes the period longer. Give only the answer to (a). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '1.501', 's', false, NULL, false, NULL, '(a) ω² = 5g/(7R) = 5 × 9.81 ÷ (7 × 0.40) = 17.5 s⁻², T = 2π ÷ √17.52 = 1.50 s. (b) Pendulum: T = 2π × √(0.40 ÷ 9.81) = 1.27 s, so the ball is 1.18 times slower. (c) Some of the energy goes into rotation, so for the same restoring force the ball accelerates less. Mark scheme (6 marks). C1: ω² = 5g/7R. A1: T = 1.50 s. C1: pendulum period. B1: comparison. B1: energy shared with rotation. B1: smaller acceleration.', 6),
('1f309e77-2462-55cc-bb31-e602b6f91064', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 44, 44, 'A mass on a spring moves with s.h.m. with a = −36x (SI units) and amplitude 0.12 m. (a) Calculate the period. (b) Calculate the maximum speed. (c) Calculate the speed when the displacement is 0.060 m. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.6235', 'm s⁻¹', false, NULL, false, NULL, '(a) ω = √36 = 6.0 rad s⁻¹, T = 2π ÷ 6.0 = 1.05 s. (b) v_max = ωx₀ = 6.0 × 0.12 = 0.72 m s⁻¹. (c) v = ω√(x₀² − x²) = 6.0 × √(0.12² − 0.060²) = 0.624 m s⁻¹. Mark scheme (5 marks). C1: ω = 6.0. A1: T. A1: v_max. C1: v = ω√(x₀² − x²). A1: v = 0.624 m s⁻¹.', 5),
('76b2cd67-dca3-500b-bec0-f6435b5a8812', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 45, 45, 'A piston moves with s.h.m. of amplitude 6.0 cm and frequency 20 Hz. (a) Calculate ω. (b) Calculate the maximum acceleration. (c) The piston head has mass 0.35 kg. Calculate the maximum resultant force on it and state where it occurs. Give only the force in (c).', NULL, 3, 'numeric'::answer_type, '331.6', 'N', false, NULL, false, NULL, '(a) ω = 2πf = 2π × 20 = 126 rad s⁻¹. (b) a_max = ω²x₀ = (126)² × 0.060 = 947 m s⁻². (c) F = ma = 0.35 × 947.5 = 332 N, at the ends of the stroke. Mark scheme (6 marks). C1: ω = 2πf. A1: ω. A1: a_max. C1: F = ma. A1: F and where. A1: F = 332 N.', 6),
('68c61b63-d358-5e86-9cf7-69719ed6c206', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 46, 46, 'A body moves with s.h.m. It takes 0.10 s to move from its equilibrium position to half its amplitude. (a) Show that this corresponds to ωt = π/6. (b) Calculate the period. (c) Calculate the time it takes to go from half the amplitude to the full amplitude. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.2', 's', false, NULL, false, NULL, '(a) x = x₀ sin ωt = x₀/2 gives sin ωt = ½, so ωt = π/6. (b) ω = (π/6) ÷ 0.10, T = 2π/ω = 12 × 0.10 = 1.2 s. (c) Equilibrium to x₀ takes T/4 = 0.30 s, so the remaining part takes 0.30 − 0.10 = 0.20 s (it moves more slowly near the end). Mark scheme (5 marks). M1: sin ωt = ½. A1: ωt = π/6. C1: T = 2π/ω. A1: T = 1.2 s. B1: 0.20 s.', 5),
('3ad3e003-6926-5c27-8fd9-bc2bfb44fc7b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 47, 47, 'A 0.50 kg block on a frictionless surface is attached to a spring of constant 200 N m⁻¹ and pulled 8.0 cm from equilibrium. (a) Show that the motion is s.h.m. (b) Calculate the frequency. (c) Calculate the speed of the block 0.050 s after release. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.346', 'm s⁻¹', false, NULL, false, NULL, '(a) F = −kx gives a = −(k/m)x, proportional to and opposite to x. (b) ω = √(200 ÷ 0.50) = 20 rad s⁻¹, f = 20 ÷ 2π = 3.18 Hz. (c) x = x₀ cos ωt, so speed = ωx₀ sin ωt. ωt = 20 × 0.050 = 1.0 rad = 57.3°: speed = 20 × 0.080 × sin 57.3° = 1.35 m s⁻¹. Mark scheme (6 marks). M1: a = −(k/m)x. C1: ω = √(k/m). A1: f. C1: v = ωx₀ sin ωt. C1: ωt in radians. A1: v = 1.35 m s⁻¹.', 6),
('9b21f2e3-bf81-513a-95a2-fbd0024c1b19', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 48, 48, 'A vertical spring–mass system oscillates with maximum acceleration 5.0 m s⁻² and maximum speed 0.50 m s⁻¹. (a) Calculate ω and the amplitude. (b) Calculate the period. (c) Explain why the mass would not lose contact with a tray it rested on. Give only the period in (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.6283', 's', false, NULL, false, NULL, '(a) ω = a_max/v_max = 5.0 ÷ 0.50 = 10 rad s⁻¹; x₀ = v_max/ω = 0.050 m. (b) T = 2π ÷ 10 = 0.628 s. (c) The maximum downward acceleration (5.0 m s⁻²) is less than g, so a tray never has to pull the mass down. Mark scheme (5 marks). C1: ω = a_max/v_max. A1: ω and x₀. A1: T = 0.628 s. B1: a_max < g. B1: contact maintained.', 5),
('94779aae-222f-533c-bafd-11d3c20c809d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 49, 49, 'A cork floats on a liquid surface disturbed by ripples, and moves up and down with s.h.m. It rises from its lowest point to its highest point, 4.0 mm higher, in 0.25 s. (a) State the amplitude and period. (b) Calculate the maximum speed. (c) Calculate the acceleration of the cork when it is 1.0 mm above its mean position. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.1579', 'm s⁻²', false, NULL, false, NULL, '(a) A = 2.0 mm, T = 0.50 s. (b) v_max = ωA = (2π ÷ 0.50) × 0.0020 = 0.0251 m s⁻¹. (c) |a| = ω²x = (2π ÷ 0.50)² × 0.0010 = 0.158 m s⁻², downwards. Mark scheme (6 marks). B1: A = 2.0 mm. B1: T = 0.50 s. C1: v_max = ωA. C1: a = −ω²x. A1: |a| = 0.158 m s⁻². B1: direction.', 6),
('06f076ec-6f06-5492-9f77-aa7b4004d4d4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'bdf389d3-533a-55ee-8bbf-e1744095737f', 'a-level', '18.4', '9702 coursebook 18.4 · Simple harmonic motion', 50, 50, 'A mass oscillates on a spring with period 0.80 s. Its maximum speed is 0.24 m s⁻¹. (a) Calculate the amplitude. (b) Calculate the speed at half the amplitude. (c) Calculate the fraction of the time the mass spends more than half the amplitude away from equilibrium. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.2078', 'm s⁻¹', false, NULL, false, NULL, '(a) x₀ = v_max/ω = 0.24 ÷ (2π ÷ 0.80) = 0.0306 m. (b) v = ω√(x₀² − x₀²/4) = v_max × √3/2 = 0.24 × √3 ÷ 2 = 0.208 m s⁻¹. (c) |x| > x₀/2 when |sin ωt| > ½, i.e. for 2/3 of each cycle. Mark scheme (5 marks). C1: x₀ = v_max/ω. A1: x₀. C1: v at x₀/2 = (√3/2)v_max. A1: v = 0.208 m s⁻¹. B1: 2/3 of the time.', 5)
