INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('d094a8e2-73b1-5bdf-bbd7-cf83fd384499', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 7, 7, 'The displacement–time graph of an s.h.m. is a sine curve. What is the shape of its velocity–time graph?', NULL, 1, 'multiple_choice'::answer_type, 'A cosine curve: the same shape shifted by a quarter of a period', NULL, false, NULL, false, NULL, 'v is the gradient of the x–t graph. The gradient of sin ωt is ω cos ωt: a sinusoid π/2 ahead. Mark scheme (1 mark). B1: C (A cosine curve: the same shape shifted by a quarter of a period).', 1),
('d43f8c8f-6aa6-5c4e-bdc5-e129d3cc0bef', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 8, 8, 'How is the acceleration–time graph of s.h.m. related to its displacement–time graph?', NULL, 1, 'multiple_choice'::answer_type, 'It is the displacement graph inverted (in antiphase) and scaled by ω²', NULL, false, NULL, false, NULL, 'a = −ω²x: same shape as x, flipped upside down. Mark scheme (1 mark). B1: A (It is the displacement graph inverted (in antiphase) and scaled by ω²).', 1),
('7c567c02-9d2f-51ed-9144-d7adb4f1b74a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 9, 9, 'On a displacement–time graph of s.h.m., where is the velocity zero?', NULL, 1, 'multiple_choice'::answer_type, 'At the peaks and troughs', NULL, false, NULL, false, NULL, 'The gradient is zero at the peaks and troughs, where the object momentarily stops. Mark scheme (1 mark). B1: D (At the peaks and troughs).', 1),
('6b61f8bd-8e04-5997-b525-3eb0179d4a69', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 10, 10, 'On a velocity–time graph of s.h.m., what does the gradient represent?', NULL, 1, 'multiple_choice'::answer_type, 'The acceleration', NULL, false, NULL, false, NULL, 'Acceleration is the rate of change of velocity: the gradient of v–t. Mark scheme (1 mark). B1: B (The acceleration).', 1),
('80d8a824-1eb7-577c-bb82-dfc63fc5b995', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 11, 11, 'A displacement–time graph of s.h.m. has peaks at +6.0 cm and the time between successive peaks is 0.80 s. Calculate the maximum speed.', NULL, 1, 'numeric'::answer_type, '0.4712', 'm s⁻¹', false, NULL, false, NULL, 'v_max = ωx₀ = (2π ÷ 0.80) × 0.060 = 0.471 m s⁻¹. Mark scheme (2 marks). C1: ω = 2π/T, v_max = ωx₀. A1: v_max = 0.471 m s⁻¹.', 2),
('8e197170-54ef-5e7f-a3bc-e56253f4ac70', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 12, 12, 'A velocity–time graph of an s.h.m. has a maximum of 0.50 m s⁻¹ and period 2.0 s. Calculate the amplitude.', NULL, 1, 'numeric'::answer_type, '0.1592', 'm', false, NULL, false, NULL, 'x₀ = v_max/ω = 0.50 ÷ (2π ÷ 2.0) = 0.159 m. Mark scheme (2 marks). C1: x₀ = v_max/ω. A1: x₀ = 0.159 m.', 2),
('c48e6dbe-76ee-581c-b924-8555c7567281', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 13, 13, 'A graph of velocity v against displacement x for s.h.m. has which shape?', NULL, 1, 'multiple_choice'::answer_type, 'An ellipse (a circle with suitable scales)', NULL, false, NULL, false, NULL, 'v² = ω²(x₀² − x²) rearranges to x²/x₀² + v²/(ωx₀)² = 1: an ellipse. Mark scheme (1 mark). B1: C (An ellipse (a circle with suitable scales)).', 1),
('6e7dd36e-797e-5e34-b684-a6e268404bae', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 14, 14, 'At t = 0 an oscillator is at its maximum positive displacement. Which equation describes its motion?', NULL, 1, 'multiple_choice'::answer_type, 'x = x₀ cos ωt', NULL, false, NULL, false, NULL, 'cos 0 = 1, so x = x₀ cos ωt starts at x₀. Mark scheme (1 mark). B1: A (x = x₀ cos ωt).', 1),
('0bce8ac4-ffd1-5e1b-9501-bf3c3c7d8d5c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 15, 15, 'An acceleration–time graph for s.h.m. has maximum value 9.0 m s⁻² and period 0.50 s. Calculate the amplitude of the motion.', NULL, 1, 'numeric'::answer_type, '0.05699', 'm', false, NULL, false, NULL, 'x₀ = a_max/ω² = 9.0 ÷ (2π ÷ 0.50)² = 0.0570 m. Mark scheme (2 marks). C1: x₀ = a_max/ω². A1: x₀ = 0.0570 m.', 2),
('4fc5933f-28a9-5055-9f89-a984e2874072', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 16, 16, 'In s.h.m., what is the phase difference between the displacement and the acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'π rad', NULL, false, NULL, false, NULL, 'a = −ω²x: the acceleration is always opposite to the displacement, so they are in antiphase. Mark scheme (1 mark). B1: D (π rad).', 1),
('e613a78a-54fc-599f-ad47-0aa01466a8d5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 17, 17, 'What does the area under a velocity–time graph of s.h.m. between t = 0 and a quarter period (starting from equilibrium) represent?', NULL, 1, 'multiple_choice'::answer_type, 'The amplitude', NULL, false, NULL, false, NULL, 'Area under v–t is displacement; from equilibrium to the extreme, the displacement is x₀. Mark scheme (1 mark). B1: B (The amplitude).', 1),
('3846ae28-b1b1-58f2-ad49-0bdd71086d06', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 18, 18, 'A displacement–time graph of a vibrating reed shows 5 complete cycles in 0.020 s. Calculate the angular frequency.', NULL, 1, 'numeric'::answer_type, '1571', 'rad s⁻¹', false, NULL, false, NULL, 'f = 5 ÷ 0.020 = 250 Hz. ω = 2πf = 2π × 250 = 1570 rad s⁻¹. Mark scheme (2 marks). C1: f from graph, ω = 2πf. A1: ω = 1570 rad s⁻¹.', 2),
('c5186bd9-ba39-59ef-9367-44e1810e48bf', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 19, 19, 'Where does the velocity–time graph of s.h.m. have its maximum values?', NULL, 1, 'multiple_choice'::answer_type, 'Where the displacement is zero', NULL, false, NULL, false, NULL, 'Speed is greatest passing through equilibrium (x = 0). Mark scheme (1 mark). B1: C (Where the displacement is zero).', 1),
('5d7012ff-11d5-5161-8503-57ecc1e9dbec', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 20, 20, 'An x–t graph of s.h.m. passes through zero moving upwards at t = 0 and first reaches its maximum at t = 0.15 s. Calculate the period.', NULL, 1, 'numeric'::answer_type, '0.6', 's', false, NULL, false, NULL, 'Zero to maximum is a quarter cycle: T = 4 × 0.15 = 0.60 s. Mark scheme (2 marks). C1: quarter period. A1: T = 0.60 s.', 2),
('a66928a7-989c-5644-8eae-8e9509536e7a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 21, 21, 'Which feature of a displacement–time graph gives the amplitude?', NULL, 1, 'multiple_choice'::answer_type, 'The height of a peak above the equilibrium line', NULL, false, NULL, false, NULL, 'Amplitude is the maximum displacement from equilibrium: the peak height. Mark scheme (1 mark). B1: A (The height of a peak above the equilibrium line).', 1),
('c92d3f21-6aa6-5737-816c-eb3e5d2b3129', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 22, 22, 'The gradient of an x–t graph of s.h.m. at the equilibrium crossing is 0.24 m s⁻¹. The amplitude is 3.0 cm. Calculate the angular frequency.', NULL, 1, 'numeric'::answer_type, '8', 'rad s⁻¹', false, NULL, false, NULL, 'At equilibrium the gradient is v_max = ωx₀, so ω = 0.24 ÷ 0.030 = 8.0 rad s⁻¹. Mark scheme (2 marks). C1: v_max = ωx₀. A1: ω = 8.0 rad s⁻¹.', 2),
('c5d0819b-a010-5e47-bd62-53b768f59c5f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 23, 23, 'An oscillator starts at x = 0 moving in the negative direction. Which describes its displacement–time graph?', NULL, 1, 'multiple_choice'::answer_type, 'An inverted sine curve, x = −x₀ sin ωt', NULL, false, NULL, false, NULL, 'Starting at zero and going negative means x = −x₀ sin ωt. Mark scheme (2 marks). C1: starts at zero, decreasing. A1: D (An inverted sine curve, x = −x₀ sin ωt).', 2),
('9025f506-ce21-5407-ae65-d957a311fd3f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 24, 24, 'A displacement–time graph of s.h.m. has amplitude 4.0 cm and period 1.2 s. Calculate the gradient of the graph at the instant the displacement is 2.0 cm.', NULL, 2, 'numeric'::answer_type, '0.1814', 'm s⁻¹', false, NULL, false, NULL, 'The gradient is the velocity: v = ω√(x₀² − x²) with ω = 2π ÷ 1.2 = 5.24 rad s⁻¹. v = 5.24 × √(0.040² − 0.020²) = 0.181 m s⁻¹. Mark scheme (3 marks). B1: gradient = velocity. C1: ω = 2π/T. C1: v = ω√(x₀² − x²).', 3),
('67d33c3a-d910-5482-a12b-0a88e577edc0', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 25, 25, 'A velocity–time graph of s.h.m. is a sine curve starting from zero and increasing. What was the displacement at t = 0?', NULL, 2, 'multiple_choice'::answer_type, 'A maximum in the negative direction (−x₀)', NULL, false, NULL, false, NULL, 'v = 0 at t = 0 so the object is at an extreme. v then becomes positive, so it is moving from −x₀ towards equilibrium. Mark scheme (3 marks). C1: v = 0 at an extreme. C1: moving in + direction from −x₀. A1: B (A maximum in the negative direction (−x₀)).', 3),
('11b913fc-db93-51c7-9d4e-0c3be4e8d08a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 26, 26, 'A v–t graph for an oscillator has a maximum of 0.62 m s⁻¹, and the time between successive maxima is 0.45 s. Calculate the maximum acceleration.', NULL, 2, 'numeric'::answer_type, '8.657', 'm s⁻²', false, NULL, false, NULL, 'a_max = ω v_max = (2π ÷ 0.45) × 0.62 = 8.66 m s⁻². Mark scheme (3 marks). C1: ω = 2π/T. C1: a_max = ωv_max. A1: a_max = 8.66 m s⁻².', 3),
('081bfa6f-80fa-53f3-8f2f-8a3899e45116', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 27, 27, 'Which statement correctly links the three graphs of s.h.m.?', NULL, 2, 'multiple_choice'::answer_type, 'v leads x by π/2, and a leads v by π/2', NULL, false, NULL, false, NULL, 'x = x₀ sin ωt, v = ωx₀ cos ωt = ωx₀ sin(ωt + π/2), a = −ω²x₀ sin ωt = ω²x₀ sin(ωt + π). Mark scheme (3 marks). C1: v leads x by π/2. C1: a leads v by π/2. A1: C (v leads x by π/2, and a leads v by π/2).', 3),
('e3623a50-17a1-5570-94e1-db1574e6dd36', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 28, 28, 'An s.h.m. obeys x = 0.080 sin(5.0t) m. Calculate the gradient of the x–t graph at t = 0.20 s.', NULL, 2, 'numeric'::answer_type, '0.2161', 'm s⁻¹', false, NULL, false, NULL, 'v = ωx₀ cos ωt = 0.080 × 5.0 × cos(1.0 rad). 1.0 rad = 57.3°, so v = 0.080 × 5.0 × cos 57.3° = 0.216 m s⁻¹. Mark scheme (4 marks). C1: v = ωx₀ cos ωt. C1: ωt in radians. C1: substitution. A1: v = 0.216 m s⁻¹.', 4),
('e991cad0-46e7-5829-9837-2c2f2c242def', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 29, 29, 'An x–t graph of s.h.m. shows x = 3.0 cm at t = 0 (a maximum) and period 2.4 s. Calculate x at t = 0.40 s.', NULL, 2, 'numeric'::answer_type, '1.5 cm', 'cm', false, NULL, false, NULL, 'ωt = 2π × 0.40 ÷ 2.4 rad, which is 60°. x = x₀ cos ωt = 3.0 × cos 60° = 1.5 cm. Mark scheme (3 marks). C1: x = x₀ cos ωt. C1: ωt = 60°. A1: x = 1.5 cm.', 3),
('7cc50b5d-dbf8-5451-b4cf-51df8229db8b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 30, 30, 'A graph of acceleration against time for s.h.m. is a cosine curve starting at its maximum positive value. Where is the object at t = 0?', NULL, 2, 'multiple_choice'::answer_type, 'At maximum negative displacement', NULL, false, NULL, false, NULL, 'a = −ω²x is maximum positive when x = −x₀. Mark scheme (3 marks). C1: a = −ω²x. C1: a max positive ⇒ x = −x₀. A1: A (At maximum negative displacement).', 3),
('abe6eb39-7adb-5245-ad08-2aa3c596e560', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 31, 31, 'A velocity–displacement graph for an oscillator is an ellipse crossing the x-axis at ±5.0 cm and the v-axis at ±0.40 m s⁻¹. Calculate the period.', NULL, 2, 'numeric'::answer_type, '0.7854', 's', false, NULL, false, NULL, 'x₀ = 0.050 m and v_max = 0.40 m s⁻¹, so ω = v_max/x₀ = 0.40 ÷ 0.050 = 8.0 rad s⁻¹. T = 2π ÷ 8.0 = 0.785 s. Mark scheme (4 marks). C1: read x₀ and v_max. C1: ω = v_max/x₀. C1: T = 2π/ω. A1: T = 0.785 s.', 4),
('05e00ecb-65e2-5003-9528-ac30625843d5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 32, 32, 'For s.h.m., which graph would be a straight line?', NULL, 2, 'multiple_choice'::answer_type, 'Acceleration against displacement', NULL, false, NULL, false, NULL, 'a = −ω²x: a straight line through the origin with negative gradient. The others are sinusoidal, elliptical and parabolic. Mark scheme (3 marks). C1: a = −ω²x. C1: linear. A1: D (Acceleration against displacement).', 3),
('f9c48670-02d9-51f8-ba82-7cdc36a38a04', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 33, 33, 'From a displacement–time graph, a student reads the period as 0.84 s and the amplitude as 2.6 cm. Calculate the maximum acceleration.', NULL, 2, 'numeric'::answer_type, '1.455', 'm s⁻²', false, NULL, false, NULL, 'ω = 2π ÷ 0.84 = 7.48 rad s⁻¹. a_max = ω²x₀ = (7.48)² × 0.026 = 1.45 m s⁻². Mark scheme (3 marks). C1: ω = 2π/T. C1: a_max = ω²x₀. A1: a_max = 1.45 m s⁻².', 3),
('29ff52d5-d4d1-5951-9cb3-1a473710688e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 34, 34, 'Two graphs show the same s.h.m.: an x–t graph and a v–t graph. At the instant the x–t graph has its steepest positive gradient, what does the v–t graph show?', NULL, 2, 'multiple_choice'::answer_type, 'Its maximum positive value', NULL, false, NULL, false, NULL, 'The gradient of x–t is v, so the steepest positive gradient is where v is maximum and positive (at x = 0). Mark scheme (4 marks). C1: gradient of x–t = v. C1: steepest = maximum v. C1: positive. A1: B (Its maximum positive value).', 4),
('5b0285dc-f767-5cfb-896f-baef810a3557', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 35, 35, 'A velocity–time graph of s.h.m. is v = 0.15 cos(10t) m s⁻¹. Calculate the area under the graph from t = 0 to t = π/20 s (a quarter period).', NULL, 2, 'numeric'::answer_type, '0.015', 'm', false, NULL, false, NULL, 'The area is the displacement from equilibrium to the extreme: the amplitude, x₀ = v_max/ω = 0.15 ÷ 10 = 0.015 m. Mark scheme (3 marks). B1: area = displacement. C1: x₀ = v_max/ω. A1: area = 0.015 m.', 3),
('08eaf741-4722-549d-9599-3ef6b5c1c884', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 36, 36, 'On a displacement–time graph for s.h.m. with period 0.60 s and amplitude 5.0 cm, starting from a maximum, calculate the displacement at t = 0.25 s.', NULL, 2, 'numeric'::answer_type, '-4.33 cm', 'cm', false, NULL, true, NULL, 'ωt = 2π × 0.25 ÷ 0.60 = 2.62 rad = 150°. x = 5.0 × cos 150° = −4.33 cm. Mark scheme (4 marks). C1: x = x₀ cos ωt. C1: ωt in radians or degrees. C1: sign. A1: x = −4.33 cm.', 4),
('3d738056-92a6-5072-bf67-7190e8dd0a9e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 37, 37, 'A student sketches the kinetic energy–time graph of an s.h.m. of period T. What is the period of the kinetic energy graph?', NULL, 2, 'multiple_choice'::answer_type, 'T/2', NULL, false, NULL, false, NULL, 'Ek ∝ v², which is maximum twice per cycle (passing equilibrium in each direction), so Ek repeats every T/2. Mark scheme (3 marks). C1: maximum twice per cycle. C1: T/2. A1: C (T/2).', 3),
('380ded80-d31d-5a0a-aab7-933a361fca72', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 38, 38, 'An x–t graph of s.h.m. crosses zero at t = 0.10 s and next crosses zero at t = 0.35 s. The amplitude is 1.5 cm. Calculate the maximum speed.', NULL, 2, 'numeric'::answer_type, '0.1885', 'm s⁻¹', false, NULL, false, NULL, 'Successive zero crossings are half a period apart: T = 2 × 0.25 = 0.50 s. v_max = ωx₀ = (2π ÷ 0.50) × 0.015 = 0.188 m s⁻¹. Mark scheme (3 marks). C1: half period between crossings. C1: v_max = ωx₀. A1: v_max = 0.188 m s⁻¹.', 3),
('f0424cf7-103a-54a9-b882-f59d8b3477a5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 39, 39, 'In a v–t graph of s.h.m., the velocity is zero at t = 0.30 s and at t = 0.70 s, and negative between them. Which is correct?', NULL, 2, 'multiple_choice'::answer_type, 'At t = 0.30 s the object is at +x₀', NULL, false, NULL, false, NULL, 'Velocity is zero at the extremes. Negative velocity follows means it moves from +x₀ towards −x₀. Period = 2 × 0.40 = 0.80 s. Mark scheme (3 marks). C1: zero velocity at extremes. C1: negative after ⇒ starts at +x₀. A1: A (At t = 0.30 s the object is at +x₀).', 3),
('0de023e5-57ab-5026-bfb7-3c15b01cc530', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 40, 40, 'A graph of acceleration a against displacement x for an oscillator is a straight line from (−0.030 m, +2.7 m s⁻²) to (+0.030 m, −2.7 m s⁻²). Calculate the period and maximum speed. Give the maximum speed.', NULL, 2, 'numeric'::answer_type, '0.2846', 'm s⁻¹', false, NULL, false, NULL, 'ω² = 2.7 ÷ 0.030 = 90 s⁻², ω = 9.49 rad s⁻¹, T = 2π/ω = 0.662 s. v_max = ωx₀ = 9.49 × 0.030 = 0.285 m s⁻¹. Mark scheme (4 marks). C1: gradient = −ω². C1: ω. C1: v_max = ωx₀. A1: v_max = 0.285 m s⁻¹.', 4),
('6b8caac4-749b-56ce-8364-524c7f769d69', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 41, 41, 'A displacement–time graph shows x = −2.0 cm at t = 0, rising to +2.0 cm at t = 0.30 s for the first time. Calculate the frequency.', NULL, 2, 'numeric'::answer_type, '1.667', 'Hz', false, NULL, false, NULL, 'From −x₀ to +x₀ is half a cycle, so T = 0.60 s and f = 1 ÷ 0.60 = 1.67 Hz. Mark scheme (3 marks). C1: half cycle. C1: f = 1/T. A1: f = 1.67 Hz.', 3),
('701339cc-7a4b-5bf1-b4f2-1d0c57226a66', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 42, 42, 'A velocity–time graph of a vibrating bridge shows v = 0.090 sin(2.5t) m s⁻¹. Calculate the amplitude of the bridge''s displacement.', NULL, 2, 'numeric'::answer_type, '0.036', 'm', false, NULL, false, NULL, 'v_max = ωx₀, so x₀ = 0.090 ÷ 2.5 = 0.036 m. Mark scheme (3 marks). B1: ω = 2.5 rad s⁻¹. C1: x₀ = v_max/ω. A1: x₀ = 0.036 m.', 3),
('9b086fe2-7daa-5433-ac9d-c413f313911b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 43, 43, 'A mass oscillates with x = 0.060 cos(4πt) m. (a) State the amplitude and period. (b) Write expressions for v and a as functions of t. (c) Calculate the velocity at t = 0.10 s, including its sign. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '-0.7171', 'm s⁻¹', false, NULL, true, NULL, '(a) x₀ = 0.060 m; ω = 4π rad s⁻¹, T = 2π/ω = 0.50 s. (b) v = −0.060 × 4π sin(4πt), a = −0.060 × (4π)² cos(4πt). (c) 4πt = 0.4π rad = 72°: v = −0.060 × 4π × sin 72° = −0.717 m s⁻¹ (moving towards −x). Mark scheme (6 marks). B1: amplitude and period. B1: v expression. B1: a expression. C1: ωt = 72°. C1: substitution. A1: v = −0.717 m s⁻¹.', 6),
('4dbe4dad-1f72-5025-aa42-ea0ed2f6033b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 44, 44, 'A displacement–time graph of a vibrating beam shows amplitude 1.2 mm and 6 complete cycles in 15 ms. (a) Calculate the frequency. (b) Calculate the maximum velocity. (c) Calculate the maximum acceleration and state where it occurs. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '7580', 'm s⁻²', false, NULL, false, NULL, '(a) T = 15 ÷ 6 = 2.5 ms, f = 400 Hz. (b) v_max = ωx₀ = 2π × 400 × 1.2 × 10⁻³ = 3.02 m s⁻¹. (c) a_max = ω²x₀ = (2π × 400)² × 1.2 × 10⁻³ = 7580 m s⁻², at the extremes of the vibration. Mark scheme (5 marks). C1: T and f. A1: f. A1: v_max. C1: a_max = ω²x₀. A1: a_max = 7580 m s⁻².', 5),
('4cf7f470-4cf3-5a27-a690-bbe3a2777c90', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 45, 45, 'A student uses a motion sensor to obtain these readings for an oscillating glider: t/s: 0, 0.10, 0.20, 0.30, 0.40; x/cm: 0, 2.9, 4.8, 4.8, 2.9. (a) Show that the data are consistent with x = 5.0 sin(ωt) cm with ω ≈ 6.3 rad s⁻¹. (b) Calculate the period. (c) Predict x at t = 0.70 s. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '-4.755 cm', 'cm', false, NULL, true, NULL, '(a) With ω = 2π rad s⁻¹: 5.0 sin(36°) = 2.9, 5.0 sin(72°) = 4.8, 5.0 sin(108°) = 4.8, 5.0 sin(144°) = 2.9 cm — all agree. (b) T = 2π/ω = 1.0 s. (c) x = 5.0 × sin(2π × 0.70 rad) = 5.0 × sin 252° = −4.76 cm. Mark scheme (6 marks). M1: substitute at least two points. A1: consistent. A1: T = 1.0 s. C1: ωt = 252°. A1: x with sign. A1: x = −4.76 cm.', 6),
('c210e0e8-6d7c-5e66-b97b-3c2a304604ec', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 46, 46, 'A sketch of velocity against displacement for an s.h.m. is an ellipse. When the mass is 3.0 cm from equilibrium its speed is 0.48 m s⁻¹; the amplitude is 5.0 cm. (a) Calculate ω. (b) Calculate the maximum speed. (c) Calculate the period. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.5236', 's', false, NULL, false, NULL, '(a) v = ω√(x₀² − x²): ω = 0.48 ÷ √(0.050² − 0.030²) = 0.48 ÷ 0.040 = 12 rad s⁻¹. (b) v_max = ωx₀ = 12 × 0.050 = 0.60 m s⁻¹. (c) T = 2π ÷ 12 = 0.524 s. Mark scheme (5 marks). C1: v = ω√(x₀² − x²). A1: ω = 12 rad s⁻¹. A1: v_max. C1: T = 2π/ω. A1: T = 0.524 s.', 5),
('63eab51c-0a20-5107-94d6-8f3d053ca0c8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 47, 47, 'An oscillator''s displacement is x = 0.040 sin(2πft) m with f = 2.5 Hz. (a) Sketch, in words, the v–t graph for one period starting at t = 0, giving the maximum value and the times it occurs. (b) Calculate the acceleration at t = 0.050 s. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '-6.979', 'm s⁻²', false, NULL, true, NULL, '(a) v = 2πf x₀ cos(2πft): a cosine curve starting at its maximum 0.628 m s⁻¹ at t = 0, zero at 0.10 s, minimum −0.628 m s⁻¹ at 0.20 s, zero at 0.30 s, maximum again at 0.40 s. (b) a = −ω²x₀ sin ωt = −(2π × 2.5)² × 0.040 × sin 45° = −6.98 m s⁻². Mark scheme (6 marks). B1: cosine shape. B1: maximum value. B1: times of maxima/zeros. C1: a = −ω²x₀ sin ωt. C1: ωt = 45°. A1: a = −6.98 m s⁻².', 6),
('f86262a7-e744-5491-9df8-697cb17a79f0', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 48, 48, 'A displacement–time graph for a mass on a spring is x = 0.050 sin(πt) m. (a) State the amplitude and period. (b) Calculate the gradient of the graph at t = 0. (c) Calculate the gradient at t = 0.50 s and explain its value. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.1571', 'm s⁻¹', false, NULL, false, NULL, '(a) x₀ = 0.050 m, ω = π rad s⁻¹ so T = 2.0 s. (b) gradient = v = ωx₀ cos ωt = π × 0.050 × cos 0 = 0.157 m s⁻¹. (c) At t = 0.50 s, ωt = 90° and cos 90° = 0: the mass is at maximum displacement, momentarily at rest. Mark scheme (5 marks). B1: amplitude and T. C1: v = ωx₀ cos ωt. A1: v = 0.157 m s⁻¹. B1: zero at 0.50 s. B1: maximum displacement.', 5),
('aab00cb3-e81b-5308-b173-fcf6bd9da32d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 49, 49, 'For an s.h.m. with amplitude 4.0 cm and period 0.50 s, a student plots v against x. (a) Describe the shape of the graph. (b) State the intercepts on both axes. (c) Calculate v at x = 3.0 cm. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.3325', 'm s⁻¹', false, NULL, false, NULL, '(a) An ellipse centred on the origin. (b) x-intercepts ±4.0 cm (v = 0), v-intercepts ±ωx₀ = ±(2π ÷ 0.50) × 0.040 = ±0.503 m s⁻¹. (c) v = ω√(x₀² − x²) = (2π ÷ 0.50) × √(0.040² − 0.030²) = 0.332 m s⁻¹. Mark scheme (6 marks). B1: ellipse. B1: x-intercepts. C1: v-intercepts ωx₀. C1: v = ω√(x₀² − x²). C1: ω = 2π/T. A1: v = 0.332 m s⁻¹.', 6),
('b529441a-982c-543e-b387-b73cf371841f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 50, 50, 'An acceleration–time graph for an oscillating object is a = −2.4 cos(4.0t) m s⁻². (a) Write the corresponding equation for x. (b) Calculate the amplitude. (c) Calculate the displacement at t = 0.30 s. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.05435', 'm', false, NULL, false, NULL, '(a) a = −ω²x with ω = 4.0 rad s⁻¹, so x = (2.4 ÷ 16) cos(4.0t). (b) x₀ = 2.4 ÷ 4.0² = 0.15 m. (c) ωt = 1.2 rad = 68.75°: x = 0.15 × cos 68.75° = 0.0544 m. Mark scheme (5 marks). B1: x = x₀ cos ωt. C1: x₀ = a_max/ω². A1: 0.15 m. C1: ωt in radians. A1: x = 0.0544 m.', 5)
